/** All translations for zizhitongjian ch.162 — Garrett M. Petersen (2026), Composer 2.5 */
export const entries = [
  { zh: "資治通鑑 第162卷卷第一百六十二", literal: "Comprehensive Mirror in Aid of Governance, Volume 162, Roll 162", idiomatic: "Comprehensive Mirror in Aid of Governance, Volume 162" },
  { zh: "【梁紀十八】　屠維大荒落，一年。", literal: "[Liang Records 18] Tuyong Dahuangluo; one year in all.", idiomatic: "[Liang Records 18] Tuyong Dahuangluo—one year in all." },
  { zh: "高祖武皇帝十八太清三年（", literal: "Great Ancestor Emperor Wu, eighteenth year of the Taqing era (", idiomatic: "Emperor Wu of Liang, eighteenth year of Taqing (" },
  { zh: "己巳，公元五四九年）", literal: "jisi, 549 CE)", idiomatic: "jisi, AD 549)" },
  { zh: "春，正月，丁巳朔，柳仲禮自新亭徙營大桁。", literal: "In spring, the first month, on the first day dingsi, Liu Zhongli moved his camp from Xinting to Daheng.", idiomatic: "In spring, the first month, on dingsi, the new moon, Liu Zhongli moved his camp from Xinting to Daheng." },
  { zh: "會大霧，韋粲軍迷失道，比及青塘，夜已過半，立柵未合，侯景望見之，亟帥銳卒攻粲。", literal: "A great fog arose; Wei Can's army lost the road, and by the time they reached Qingtang, more than half the night had passed and their palisade was not yet closed. Hou Jing saw them and at once led crack troops to attack Can.", idiomatic: "A thick fog fell. Wei Can's army lost the road; by the time they reached Qingtang, half the night was gone and their palisade was still open. Hou Jing saw them and led crack troops straight at Can." },
  { zh: "粲使軍主鄭逸逆擊之，命劉叔胤以舟師截其後，叔胤畏心需不敢進，逸遂敗。", literal: "Can sent Army Commander Zheng Yi to strike back; he ordered Liu Shuyin to cut off the rear with river forces, but Shuyin, fearing and hesitant, dared not advance, and Yi was defeated.", idiomatic: "Can sent army commander Zheng Yi to counterattack and ordered Liu Shuyin to block the rear with river troops. Shuyin, afraid and wavering, would not advance—and Yi was beaten." },
  { zh: "景乘勝入粲營，左右牽粲避賊，粲不動，叱子弟力戰，遂與子尼及三弟助、警、構、從弟昂皆戰死，親戚死者數百人。", literal: "Jing pressed the victory into Can's camp; attendants pulled Can to flee the bandits, but Can did not move, shouted at sons and younger brothers to fight hard, and then he, his son Ni, three younger brothers Zhu, Jing, and Gou, and cousin Ang all died in battle; kinsmen dead numbered in the hundreds.", idiomatic: "Jing drove the victory into Can's camp. Attendants tried to pull Can away; he would not budge and shouted his sons and brothers to fight. He fell with his son Ni, three younger brothers Zhu, Jing, and Gou, and cousin Ang; hundreds of kin died with them." },
  { zh: "仲禮方食，投箸被甲，與其麾下百騎馳往救之，與景戰於青塘，大破之，斬首數百級，沉淮水死者千餘人。", literal: "Zhongli was at meal, cast down his chopsticks, donned armor, and with a hundred horsemen of his command galloped to rescue; he fought Jing at Qingtang, routed him greatly, beheaded several hundred, and more than a thousand drowned in the Huai.", idiomatic: "Zhongli was eating when he threw down his chopsticks, armored, and galloped with a hundred riders to the rescue. At Qingtang he smashed Jing's force—several hundred heads taken, more than a thousand drowned in the Huai." },
  { zh: "仲禮槊將及景，而賊將支伯仁自後斫仲禮中肩，馬陷於淖，賊聚槊刺之，騎將郭山石救之，得免。", literal: "Zhongli's spear was about to reach Jing when bandit general Zhi Boren hacked him between the shoulders from behind; his horse sank in mud, bandits gathered spears to stab him, and cavalry commander Guo Shanshi rescued him—he escaped.", idiomatic: "Zhongli's spear was almost on Jing when bandit general Zhi Boren struck him between the shoulders from behind. His horse sank in the mire; bandits piled on with spears until cavalry commander Guo Shanshi pulled him free." },
  { zh: "仲禮被重瘡，會稽人惠□吮瘡斷血，故得不死。", literal: "Zhongli suffered grave wounds; a Kuaiji man named Hui□ sucked the wound and stanched the blood, so he did not die.", idiomatic: "Zhongli was gravely wounded. A man of Kuaiji named Hui□ sucked the wound and stanched the blood, and so he lived." },
  { zh: "自是景不敢復濟南岸，仲禮亦氣衰，不復言戰矣。", literal: "From this Jing dared not cross the south bank again; Zhongli also waned in spirit and spoke of battle no more.", idiomatic: "After that Jing dared not cross the south bank again. Zhongli's spirit faded too, and he spoke of fighting no more." },
  { zh: "邵陵王綸復收散卒，與東揚州刺史臨城公大連、新淦公大成等自東道並至；", literal: "Prince of Shaoling Lun again gathered scattered troops and, with Eastern Yangzhou Inspector Prince of Lincheng Dalian, Prince of Xingan Dacheng, and others, all arrived by the eastern route;", idiomatic: "Prince Lun of Shaoling gathered scattered troops again and arrived by the eastern route with Eastern Yangzhou inspector Prince Dalian of Lincheng, Prince Dacheng of Xingan, and others;" },
  { zh: "庚申，列營於桁南，亦推柳仲禮為大都督。", literal: "On gengshen they arrayed camps south of the bridge and likewise made Liu Zhongli Grand Commander.", idiomatic: "On gengshen they encamped south of the bridge and again chose Liu Zhongli as grand commander." },
  { zh: "大連，大臨之弟也。", literal: "Dalian was the younger brother of Dalin.", idiomatic: "Dalian was the younger brother of Xiao Dalin." },
  { zh: "朝野以侯景之禍共尤朱異，異慚憤發疾，庚申，卒。", literal: "Court and commonalty together blamed Zhu Yi for Hou Jing's disaster; Yi, ashamed and angry, fell ill, and on gengshen he died.", idiomatic: "Court and people alike blamed Zhu Yi for Hou Jing's disaster. Yi, shamed and furious, took ill and died on gengshen." },
  { zh: "故事，尚書官不以為贈。", literal: "By precedent, Masters of Writing posts were not granted posthumous honors.", idiomatic: "By precedent, ministers of the Masters of Writing were not granted posthumous honors." },
  { zh: "上痛惜異，特贈尚書右僕射。", literal: "The emperor grieved for Yi and specially granted him Right Vice Minister of the Masters of Writing.", idiomatic: "The emperor grieved for Yi and specially granted him right vice minister of the Masters of Writing." },
  { zh: "甲子，湘東世子方等及王僧辯軍至。", literal: "On jiazi, Xiangdong Heir Fangdeng and Wang Senbian's army arrived.", idiomatic: "On jiazi, Xiangdong heir Fangdeng and Wang Senbian's army arrived." },
  { zh: "戊辰，封山侯正表以北徐州降東魏，東魏徐州刺史高歸彥遣兵赴之。", literal: "On wuchen, Marquis Zhengbiao of Fengshan surrendered Northern Xuzhou to Eastern Wei; Eastern Wei Xuzhou Inspector Gao Guiyan sent troops to him.", idiomatic: "On wuchen, Marquis Zhengbiao of Fengshan surrendered Northern Xuzhou to Eastern Wei; Eastern Wei Xuzhou inspector Gao Guiyan sent troops to support him." },
  { zh: "歸彥，歡之族弟也。", literal: "Guiyan was a clansman younger brother of Huan.", idiomatic: "Guiyan was a clansman of Gao Huan." },
  { zh: "己巳，太子遷居永福省。", literal: "On jisi the crown prince moved residence to Yongfu Palace.", idiomatic: "On jisi the crown prince moved to Yongfu Palace." },
  { zh: "高州刺史李遷仕、天門太守樊文皎將援兵萬餘人至城下。", literal: "Gaozhou Inspector Li Qianshi and Tianmen Administrator Fan Wenjiao led more than ten thousand relief troops to below the city.", idiomatic: "Gaozhou inspector Li Qianshi and Tianmen administrator Fan Wenjiao brought more than ten thousand relief troops to the city." },
  { zh: "台城與援軍信命久絕，有羊車兒獻策，作紙鴟，系以長繩，寫敕於內，放以從風，冀達眾軍，題云：「得鴟送援軍，賞銀百兩。", literal: "Taicheng and the relief armies had long been cut off from messages; a man named Yang Che'er offered a plan—to make paper kites, tie them with long cords, write orders inside, release them on the wind hoping to reach the armies, with an inscription: \"Whoever delivers a kite to the relief armies will be rewarded a hundred taels of silver.", idiomatic: "Taicheng and the relief armies had long lost contact. A man named Yang Che'er proposed paper kites on long cords with orders inside, sent on the wind toward the armies. The label read: \"Deliver this kite to the relief armies and receive a hundred taels of silver." },
  { zh: "」太子自出太極殿前乘西北風縱之，賊怪之，以為厭勝，射而下之。", literal: "\" The crown prince himself came out before the Hall of Supreme Pole, rode the northwest wind to release them; the bandits thought it strange, took it for sorcery against them, and shot them down.", idiomatic: "\" The crown prince released them himself before the Hall of Supreme Pole on the northwest wind. The bandits took it for witchcraft, shot them down." },
  { zh: "援軍募人能入城送啟者，鄱陽世子嗣左右李朗請先受鞭，詐為得罪，叛投賊，因得入城，城中方知援兵四集，舉城鼓噪。", literal: "The relief armies recruited men who could enter the city with dispatches; Li Lang, attendant to Poyang Heir Si, asked first to be whipped, pretended offense, defected to the bandits, and thus entered the city. Only then did the city learn relief was gathering on all sides, and the whole city shouted in joy.", idiomatic: "The relief armies sought men who could slip dispatches into the city. Li Lang, attendant to Poyang heir Si, asked to be whipped first, feigned disgrace, and defected to the bandits—thus entering the city. The city learned relief was gathering everywhere and erupted in cheers." },
  { zh: "上以朗為直閣將軍，賜金遣之。", literal: "The emperor made Lang Direct Gate General, gave him gold, and sent him off.", idiomatic: "The emperor made Lang a direct gate general, gave him gold, and sent him back." },
  { zh: "朗緣鐘山之後，宵行晝伏，積日乃達。", literal: "Lang went along the rear of Zhong Mountain, marching by night and hiding by day; many days passed before he arrived.", idiomatic: "Lang skirted Zhong Mountain, traveling by night and hiding by day, and only after many days reached his goal." },
  { zh: "癸未，鄱陽世子嗣、永安侯確、莊鐵、羊鴉仁、柳敬禮、李遷仕、樊文皎將兵度淮，攻東府前柵，焚之；", literal: "On guiwei, Poyang Heir Si, Marquis Que of Yong'an, Zhuang Tie, Yang Yaren, Liu Jingli, Li Qianshi, and Fan Wenjiao led troops across the Huai, attacked the front palisade of the Eastern Quarter, and burned it;", idiomatic: "On guiwei, Poyang heir Si, Marquis Que of Yong'an, Zhuang Tie, Yang Yaren, Liu Jingli, Li Qianshi, and Fan Wenjiao crossed the Huai, stormed the Eastern Quarter's front palisade, and burned it;" },
  { zh: "侯景退。", literal: "Hou Jing withdrew.", idiomatic: "Hou Jing withdrew." },
  { zh: "眾軍營於青溪之東，遷仕、文皎帥銳卒五千獨進深入，所向摧靡。", literal: "The armies encamped east of Qing Stream; Qianshi and Wenjiao led five thousand crack troops forward alone in depth, crushing all before them.", idiomatic: "The armies camped east of Qing Stream. Qianshi and Wenjiao led five thousand crack troops in a lone deep thrust and swept all before them." },
  { zh: "至菰首橋東，景將宋子仙伏兵擊之，文皎戰死，遷仕遁還。", literal: "At the east of Gushou Bridge, Jing's general Song Zixian with hidden troops struck them; Wenjiao died in battle and Qianshi fled back.", idiomatic: "East of Gushou Bridge, Jing's general Song Zixian ambushed them. Wenjiao fell in battle; Qianshi fled back." },
  { zh: "敬禮，仲禮之弟也。", literal: "Jingli was Zhongli's younger brother.", idiomatic: "Jingli was Liu Zhongli's younger brother." },
  { zh: "仲禮神情傲很，陵蔑諸將，邵陵王綸每日執鞭至門，亦移時弗見，由是與綸及臨城公大連深相仇怨。", literal: "Zhongli's bearing was proud and harsh; he looked down on the generals. Prince of Shaoling Lun daily came to the gate holding a whip and still waited long without being received—therefore he and Lun and Prince of Lincheng Dalian nursed deep mutual hatred.", idiomatic: "Zhongli was proud and harsh and looked down on the other generals. Prince Lun of Shaoling came daily to his gate with whip in hand and still waited long without audience. He and Lun and Prince Dalian of Lincheng came to hate each other deeply." },
  { zh: "大連又與永安侯確有隙，諸軍互相猜阻，莫有戰心。", literal: "Dalian also had a rift with Marquis Que of Yong'an; the armies mutually suspected and blocked one another, and none had heart to fight.", idiomatic: "Dalian also feuded with Marquis Que of Yong'an. The armies suspected one another and none would fight." },
  { zh: "援軍初至，建康士民扶老攜幼以候之，才過淮，即縱兵剽掠。", literal: "When the relief armies first arrived, Jiankang gentry and commoners, supporting the old and leading the young, waited for them—but once they had crossed the Huai they at once let soldiers plunder.", idiomatic: "When relief first arrived, Jiankang people old and young came out to welcome them. They had barely crossed the Huai before the soldiers began to plunder." },
  { zh: "由是士民失望，賊中有謀應官軍者，聞之，亦止。", literal: "Thereby gentry and commoners lost hope; among the bandits were some plotting to join the official armies, and hearing this, they also stopped.", idiomatic: "The people lost hope. Bandits who had planned to turn to the imperial armies heard of it and stopped." },
  { zh: "王顯貴以壽陽降東魏。", literal: "Wang Xiangui surrendered Shouchun to Eastern Wei.", idiomatic: "Wang Xiangui surrendered Shouchun to Eastern Wei." },
  { zh: "臨賀王記室吳郡顧野王起兵討侯景，二月，己丑，引兵來至。", literal: "Recorder of Prince of Linhe Gu Yewang of Wu commandery raised troops to attack Hou Jing; in the second month, on jichou, he led his army and arrived.", idiomatic: "Gu Yewang of Wu, recorder to Prince of Linhe, raised troops against Hou Jing. In the second month, on jichou, he arrived with his army." },
  { zh: "初，台城之閉也，公卿以食為念，男女貴賤並出負米，得四十萬斛，收諸府藏錢帛五十萬億，並聚德陽堂，而不備薪芻、魚鹽。", literal: "At first, when Taicheng was closed, the high officials thought only of food; men and women, noble and base, all went out carrying rice and got four hundred thousand hu; they gathered fifty trillion in cash and silk from the various treasuries, all piled in the Hall of Virtue and Yang—but they did not prepare firewood, fodder, fish, or salt.", idiomatic: "When Taicheng was first sealed, officials thought only of food. Nobles and commoners alike carried in rice until they had four hundred thousand hu. They gathered fifty trillion in coin and silk from the treasuries into the Hall of Virtue and Yang—but never laid in firewood, fodder, fish, or salt." },
  { zh: "至是，壞尚書省為薪。", literal: "By now they demolished the Masters of Writing office for firewood.", idiomatic: "By then they were tearing down the Masters of Writing office for firewood." },
  { zh: "撤薦，坐刀以飼馬。", literal: "They stripped matting and sat on swords to feed the horses.", idiomatic: "They stripped matting and used swords as seats to feed the horses." },
  { zh: "薦盡，又食以飯。", literal: "When matting was gone, they fed them rice.", idiomatic: "When the matting was gone, they fed the horses rice." },
  { zh: "軍士無□，或煮鎧、熏鼠、捕雀而食之。", literal: "Soldiers had no □; some boiled armor, smoked rats, or caught sparrows and ate them.", idiomatic: "Soldiers had nothing □; some boiled armor, smoked rats, caught sparrows, and ate them." },
  { zh: "御甘露廚有干苔，味酸鹹，分給戰士。", literal: "The imperial Sweet Dew kitchen had dried moss, sour and salty in taste, which was divided among the fighting men.", idiomatic: "The imperial Sweet Dew kitchen had dried moss, sour and salty, which was divided among the soldiers." },
  { zh: "軍人屠馬於殿省間，雜以人肉，食者必病。", literal: "Soldiers slaughtered horses between the palace halls; human flesh was mixed in, and those who ate it always fell ill.", idiomatic: "Soldiers butchered horses in the palace halls, mixed in human flesh, and all who ate fell sick." },
  { zh: "侯景眾亦饑，抄掠無所獲；", literal: "Hou Jing's host was also hungry; raiding yielded nothing;", idiomatic: "Hou Jing's men were hungry too; raiding yielded nothing;" },
  { zh: "東城有米，可支一年，援軍斷其路。", literal: "the Eastern Quarter had grain enough for a year, but the relief armies cut its route.", idiomatic: "the Eastern Quarter had grain for a year, but relief armies cut the supply line." },
  { zh: "又聞荊州兵將至，景甚患之。", literal: "He also heard Jingzhou troops were about to arrive, and Jing was greatly troubled.", idiomatic: "He also heard Jingzhou troops were coming, and Jing was deeply alarmed." },
  { zh: "王偉曰：「今台城不可猝拔，援兵日盛，吾軍乏食，若偽且求和以緩其勢，東城之米，足支一年，因求和之際，運米入石頭，援軍必不得動，然後休士息馬，繕修器械，伺其懈怠擊之，一舉可取也。", literal: "Wang Wei said: \"Now Taicheng cannot be taken in a rush; relief grows daily and our army lacks food. If we falsely seek peace for now to slacken their momentum—the Eastern Quarter's grain can last a year—then while seeking peace, transport grain into Shitou; the relief armies surely cannot move. Then rest men and horses, repair weapons, wait for their slackness and strike—one blow can take it.", idiomatic: "Wang Wei said: \"Taicheng cannot be stormed now; relief grows daily and we are starving. Feign peace to slow them—the Eastern Quarter's grain can last a year. While they think we negotiate, move grain into Shitou. Relief armies will not dare move. Then rest the men, repair arms, wait for slackness, and strike—one blow will take it." },
  { zh: "」景從之，遣其將任約、於子悅至城下，拜表求和，乞復先鎮。", literal: "\" Jing followed this, sent his generals Ren Yue and Yu Ziyue to below the city, bowed with a memorial seeking peace, and asked to return to his former garrison.", idiomatic: "\" Jing agreed and sent Ren Yue and Yu Ziyue below the walls with a memorial begging peace and asking to return to his former post." },
  { zh: "太子以城中窮困，白上，請許之。", literal: "The crown prince, because the city was destitute, reported to the emperor and asked to grant it.", idiomatic: "The crown prince, seeing the city's misery, reported to the emperor and asked permission." },
  { zh: "上怒曰：「和不如死！", literal: "The emperor in anger said: \"Peace is worse than death!", idiomatic: "The emperor raged: \"Peace is worse than death!" },
  { zh: "」太子固請曰：「侯景圍逼已久，援軍相仗不戰，宜且許其和，更為後圖。", literal: "\" The crown prince firmly pleaded: \"Hou Jing has pressed the siege long; the relief armies lean on one another and will not fight. We should grant peace for now and plan again.", idiomatic: "\" The crown prince pressed him: \"Hou Jing has besieged us long; relief armies hang back and will not fight. Grant peace for now and plan again." },
  { zh: "」上遲回久之，乃曰：「汝自圖之，勿令取笑千載。", literal: "\" The emperor hesitated long, then said: \"You figure it out yourself—do not let us be mocked for a thousand years.", idiomatic: "\" The emperor hesitated a long while, then said: \"Handle it yourself—do not make us a laughingstock for a thousand years." },
  { zh: "」遂報許之。", literal: "\" Then he replied granting it.", idiomatic: "\" He agreed." },
  { zh: "景乞割江右四州之地，並求宣城王大器出送，然後濟江。", literal: "Jing asked to cede the four provinces west of the river and also demanded that Prince of Xuancheng Daqi escort him out before he would cross the river.", idiomatic: "Jing demanded the four provinces west of the river and Prince Daqi of Xuancheng as escort before he would cross the Yangtze." },
  { zh: "中領軍傅岐固爭曰：「豈有賊舉兵圍宮闕而更與之和乎！", literal: "Central Army Commander Fu Qi stubbornly argued: \"How can there be peace with a bandit who raised troops and besieged the palace!", idiomatic: "Central army commander Fu Qi argued fiercely: \"How can we make peace with a rebel who besieged the palace!" },
  { zh: "此特欲卻援軍耳。", literal: "\"This is only to drive off the relief armies.", idiomatic: "\"This is only to drive off relief." },
  { zh: "戎狄獸心，必不可信。", literal: "\"Barbarians have the hearts of beasts—surely they cannot be trusted.", idiomatic: "\"Barbarians have beasts' hearts—they cannot be trusted." },
  { zh: "且宣城嫡嗣之重，國命所繫，豈可為質！", literal: "\"Moreover the weight of Xuancheng's legitimate heir binds the fate of the state—how can he be made a hostage!\"", idiomatic: "\"And Xuancheng's legitimate heir holds the fate of the realm—he cannot be a hostage!\"" },
  { zh: "」上乃以大器之弟石城公大款為侍中，出質於景。", literal: "\" The emperor then made Daqi's younger brother Prince of Shicheng Dakuan Palace Attendant and sent him out as hostage to Jing.", idiomatic: "\" The emperor sent Daqi's younger brother Prince Dakuan of Shicheng, made palace attendant, as hostage to Jing instead." },
  { zh: "又敕諸軍不得復進，下詔曰：「善兵不戰，止戈為武。", literal: "He also ordered the armies not to advance again and issued an edict: \"Good soldiers do not fight; stopping the spear is martial virtue.", idiomatic: "He ordered the armies not to advance and issued an edict: \"The best soldier does not fight; to stop the spear is true martial virtue." },
  { zh: "可以景為大丞相，都督江西四州諸軍事，豫州牧、河南王如故。", literal: "\"Let Jing be Grand Chancellor, Commander-in-Chief of all military affairs of the four provinces west of the river, Governor of Yuzhou and King of Henan as before.", idiomatic: "\"Let Jing be grand chancellor, commander of the four provinces west of the river, governor of Yuzhou and King of Henan as before." },
  { zh: "」己亥，設壇於西華門外，遣僕射王克、上甲侯韶、吏部郎蕭瑳與於子悅、任約、王偉登壇共盟。", literal: "\" On jihai an altar was set outside the Western Splendor Gate; Vice Minister Wang Ke, Senior Armorer Hou Shao, and Personnel Section Chief Xiao Chen, with Yu Ziyue, Ren Yue, and Wang Wei, ascended the altar and swore together.", idiomatic: "\" On jihai they raised an altar outside the Western Splendor Gate. Vice minister Wang Ke, senior armorer Hou Shao, and personnel chief Xiao Chen swore with Yu Ziyue, Ren Yue, and Wang Wei." },
  { zh: "太子詹事柳津出西華門，景出柵門，遙相對，更殺牲歃血為盟。", literal: "Crown Prince Household Governor Liu Jin went out the Western Splendor Gate; Jing went out the palisade gate; facing each other from afar, they again killed victims and drank blood to seal the oath.", idiomatic: "Crown prince household governor Liu Jin went out the Western Splendor Gate; Jing came out the palisade gate. Facing each other from afar, they slaughtered victims and drank blood to seal the oath." },
  { zh: "既盟，而景長圍不解，專修鎧仗，托云「無船，不得即發」，又云「恐南軍見躡」，遣石城公還台，求宣城王出送；", literal: "After the oath, Jing's long siege did not lift; he devoted himself to armor and weapons, pleading \"no boats—cannot depart at once,\" and also \"fearing southern armies will pursue,\" sent Prince of Shicheng back to the capital, and asked for Prince of Xuancheng to escort him out;", idiomatic: "After the oath Jing kept the siege tight and repaired arms and armor, claiming \"no boats—we cannot leave yet\" and \"fearing pursuit from the south.\" He sent Prince Dakuan of Shicheng back and again demanded Prince of Xuancheng as escort;" },
  { zh: "邀求稍廣，了無去志。", literal: "his demands grew wider, and he had no mind to leave at all.", idiomatic: "his demands widened, and he had no intention of leaving." },
  { zh: "太子知其詐言，猶羈縻不絕。", literal: "The crown prince knew his deceit but still kept him on a loose tether without breaking off.", idiomatic: "The crown prince knew it was deceit but still kept the pretense alive." },
  { zh: "韶，懿之孫也。", literal: "Shao was the grandson of Yi.", idiomatic: "Shao was the grandson of Xiao Yi." },
  { zh: "庚子，前南兗州刺史南康王會理、前青冀二州刺史湘潭侯退、西昌侯世子彧眾合三萬，至於馬卬洲，景慮其自白下而上，啟云：「請敕北軍聚還南岸，不爾，妨臣濟江。", literal: "On gengzi, former Southern Yanzhou Inspector Prince of Nankang Huili, former Qing-Ji Inspector Marquis Tui of Xiangtan, and Xichang Heir Yu together mustered thirty thousand and reached Mayang Isle. Jing feared they would come up from Baixia and memorialized: \"Please order the northern armies gathered back to the south bank; otherwise they will hinder my crossing the river.", idiomatic: "On gengzi, former Southern Yanzhou inspector Prince Huili of Nankang, former Qing-Ji inspector Marquis Tui of Xiangtan, and Xichang heir Yu mustered thirty thousand at Mayang Isle. Jing feared an attack from Baixia and wrote: \"Order the northern armies back to the south bank, or they will block my crossing." },
  { zh: "」太子即勒會理自白下城移軍江潭苑。", literal: "\" The crown prince at once ordered Huili to move his army from Baixia city to the Jiangtan Garden.", idiomatic: "\" The crown prince at once ordered Huili to move from Baixia to the Jiangtan Garden." },
  { zh: "退，恢之子也。", literal: "Tui was the son of Hui.", idiomatic: "Tui was the son of Xiao Hui." },
  { zh: "辛丑，以邵陵王綸為司空，鄱陽王范為征北將軍，柳仲禮為侍中、尚書右僕射。", literal: "On xinchou, Prince of Shaoling Lun was made Minister of Works, Prince of Poyang Fan was made General Who Conquers the North, and Liu Zhongli was made Palace Attendant and Right Vice Minister of the Masters of Writing.", idiomatic: "On xinchou, Prince Lun of Shaoling was made minister of works, Prince Fan of Poyang general who conquers the north, and Liu Zhongli palace attendant and right vice minister of the Masters of Writing." },
  { zh: "景以於子悅、任約、傅士悊皆為儀同三司，夏侯譒為豫州刺史，董紹先為東徐州刺史，徐思玉為北徐州刺史，王偉為散騎常侍。", literal: "Jing made Yu Ziyue, Ren Yue, and Fu Shiti all Acting Three Excellencies, Xiahou Zan Yuzhou Inspector, Dong Shaoxian Eastern Xuzhou Inspector, Xu Siyu Northern Xuzhou Inspector, and Wang Wei Regular Attendant of the Scattered Cavalry.", idiomatic: "Jing made Yu Ziyue, Ren Yue, and Fu Shiti acting three excellencies; Xiahou Zan Yuzhou inspector; Dong Shaoxian Eastern Xuzhou inspector; Xu Siyu Northern Xuzhou inspector; and Wang Wei regular attendant of the scattered cavalry." },
  { zh: "上以偉為侍中。", literal: "The emperor made Wei Palace Attendant.", idiomatic: "The emperor made Wei a palace attendant." },
  { zh: "乙卯，景又啟曰：「適有西岸信至，高澄已得壽陽、鐘離，臣今無所投足，求借廣陵並譙州，俟得壽陽，即奉還朝廷。", literal: "On yimao, Jing again memorialized: \"Just now word came from the west bank—Gao Cheng has taken Shouchun and Zhongli; your servant now has nowhere to set foot. I ask to borrow Guangling and Qiao province; once I regain Shouchun I will return them to the court.", idiomatic: "On yimao Jing wrote again: \"Word just came from the west bank—Gao Cheng has taken Shouchun and Zhongli. I have nowhere to stand. Lend me Guangling and Qiao province; once I retake Shouchun I will return them to the court." },
  { zh: "」又云：「援軍既在南岸，須於京口渡江。", literal: "\" He also said: \"Since relief armies are on the south bank, they must cross the river at Jingkou.", idiomatic: "\" He added: \"Relief is on the south bank—they must cross at Jingkou." },
  { zh: "」太子並答許之。", literal: "\" The crown prince answered granting all.", idiomatic: "\" The crown prince agreed to all." },
  { zh: "癸卯，大赦。", literal: "On guimao, a general amnesty.", idiomatic: "On guimao, a general amnesty." },
  { zh: "庚戌，景又啟曰：「永安侯確、直閤趙威方頻隔柵見詬云：『天子自與汝盟，我終當破汝。", literal: "On gengxu, Jing again memorialized: \"Marquis Que of Yong'an and Direct Gate Attendant Zhao Weifang often reviled us across the palisade, saying: 'The Son of Heaven made peace with you himself—I will still break you.", idiomatic: "On gengxu Jing wrote again: \"Marquis Que of Yong'an and direct gate attendant Zhao Weifang keep shouting across the palisade: 'The Son of Heaven made peace with you—I will still destroy you." },
  { zh: "』乞召侯及威方入，即當引路。", literal: "' I ask that the marquis and Weifang be summoned in—I will guide the way at once.", idiomatic: "' Summon the marquis and Weifang—I will guide them in at once." },
  { zh: "」上遣吏部尚書張綰召確，辛亥，以確為廣州刺史，威方為盱眙太守。", literal: "\" The emperor sent Minister of Personnel Zhang Wan to summon Que; on xinhai he made Que Guangzhou Inspector and Weifang Xuyi Administrator.", idiomatic: "\" The emperor sent minister of personnel Zhang Wan for Que. On xinhai he made Que Guangzhou inspector and Weifang Xuyi administrator." },
  { zh: "確累啟固辭，不入，上不許。", literal: "Que repeatedly memorialized firmly refusing and would not enter; the emperor would not allow it.", idiomatic: "Que repeatedly refused and would not enter; the emperor would not hear of it." },
  { zh: "確先遣威方入城，因欲南奔。", literal: "Que first sent Weifang into the city, intending then to flee south.", idiomatic: "Que sent Weifang into the city first, planning to flee south himself." },
  { zh: "邵陵王綸泣謂確曰：「圍城既久，聖上憂危，臣子之情，切於湯火，故欲且盟而遣之，更申後計。", literal: "Prince of Shaoling Lun weeping said to Que: \"The siege has lasted long; the sage sovereign is in peril. A subject's feeling cuts like boiling water and fire—therefore we mean to make peace for now and send you in, then plan again.", idiomatic: "Prince Lun of Shaoling wept and told Que: \"The siege has lasted long; the emperor is in peril. A subject's duty burns like fire—we mean to make peace for now and send you in, then plan again." },
  { zh: "成命已決，何得拒違！", literal: "\"The settled order is decided—how can you refuse and disobey!\"", idiomatic: "\"The order is set—how can you refuse!\"" },
  { zh: "」時台使周石珍、東宮主書左法生在綸所，確謂之曰：「侯景雖雲欲去而不解長圍，意可見也。", literal: "\" At the time capital envoy Zhou Shizhen and Eastern Palace Chief Clerk Zuo Fasheng were at Lun's quarters; Que said to them: \"Though Hou Jing says he wishes to leave, he does not lift the long siege—his intent is plain.", idiomatic: "\" Capital envoy Zhou Shizhen and Eastern Palace chief clerk Zuo Fasheng were with Lun. Que told them: \"Hou Jing says he will leave but keeps the siege—his intent is plain." },
  { zh: "今召僕入城，何益於事！", literal: "\"Now summoning me into the city—what good is it to the affair!\"", idiomatic: "\"Summoning me into the city now—what good will it do!\"" },
  { zh: "」石珍曰：「敕旨如此，郎那得辭！", literal: "\" Shizhen said: \"The imperial order is thus—how can you, sir, decline!\"", idiomatic: "\" Shizhen said: \"That is the imperial order—you cannot refuse!\"" },
  { zh: "」確意尚堅，綸大怒，謂趙伯超曰：「譙州為我斬之！", literal: "\" Que's resolve was still firm; Lun in great anger said to Zhao Bochao: \"Qiao province—behead him for me!\"", idiomatic: "\" Que still refused. Lun raged and told Zhao Bochao: \"Qiao province—cut off his head for me!\"" },
  { zh: "持其首去！", literal: "\"Take his head and go!\"", idiomatic: "\"Take his head and go!\"" },
  { zh: "」伯超揮刃眄確曰：「伯超識君侯，刀不識也！", literal: "\" Bochao flourished his blade and glanced at Que: \"Bochao knows my lord; the blade does not know him!\"", idiomatic: "\" Bochao raised his blade and looked at Que: \"Bochao knows you, my lord—the blade does not!\"" },
  { zh: "」確乃流涕入城。", literal: "\" Que then wept and entered the city.", idiomatic: "\" Que wept and entered the city." },
  { zh: "上常蔬食，及圍城日久，上廚蔬茹皆絕，乃食雞子。", literal: "The emperor usually ate vegetables; as the siege lengthened, vegetables in the imperial kitchen were exhausted, and he ate eggs.", idiomatic: "The emperor usually ate plain food. As the siege dragged on and vegetables ran out, he ate eggs." },
  { zh: "綸因使者暫通，上雞子數百枚，上手自料簡，歔欷哽咽。", literal: "Lun, because messengers briefly got through, sent up several hundred eggs; the emperor personally sorted them, sighing and choking.", idiomatic: "Lun, when messengers briefly got through, sent several hundred eggs. The emperor sorted them himself, sighing and choking back tears." },
  { zh: "湘東王繹軍於郢州之武城，湘州刺史河東王譽軍於青草湖，信州刺史桂陽王慥軍於西峽口，托雲俟四方援兵，淹留不進。", literal: "Prince of Xiangdong Yi encamped at Wucheng in Ying province; Prince of Hedong Yu, Xiangzhou Inspector, encamped at Green Grass Lake; Prince of Guiyang Chao, Xinzhou Inspector, encamped at West Gorge Mouth—all claiming to await relief from all quarters, they lingered and did not advance.", idiomatic: "Prince Yi of Xiangdong camped at Wucheng in Ying province; Xiangzhou inspector Prince Yu of Hedong at Green Grass Lake; Xinzhou inspector Prince Chao of Guiyang at West Gorge Mouth—all claiming to await relief from every quarter, they lingered and did not advance." },
  { zh: "中記室參軍蕭賁，骨鯁士也，以繹不早下，心非之；", literal: "Middle Recorder Army Adjutant Xiao Ben was a man of stiff backbone; because Yi did not march down early, he disapproved in his heart;", idiomatic: "Middle recorder army adjutant Xiao Ben was a man of stiff spine; he disapproved that Yi would not march down early;" },
  { zh: "嘗與繹雙六，食子未下，賁曰：「殿下都無下意。", literal: "once playing backgammon with Yi, a piece not yet placed, Ben said: \"Your Highness has no mind to move at all.", idiomatic: "once playing backgammon with Yi, before a piece was placed Ben said: \"Your Highness has no mind to move at all." },
  { zh: "」繹深銜之。", literal: "\" Yi deeply resented it.", idiomatic: "\" Yi deeply resented it." },
  { zh: "及得上敕，繹欲旋師，賁曰：「景以人臣舉兵向闕，今若放兵，未及渡江，童子能斬之矣，必不為也。", literal: "When he received the imperial order, Yi wished to turn the army back; Ben said: \"Jing as a subject raised troops against the palace gates—if he now disbands his army, before he even crosses the river a child could behead him; he surely will not do it.", idiomatic: "When the imperial order arrived, Yi meant to withdraw. Ben said: \"Jing raised troops against the throne as a subject. If he disbands now, a child could cut him down before he crosses the river—he will never do it." },
  { zh: "大王以十萬之眾，未見賊而退，奈何！", literal: "\"Your Highness with a host of a hundred thousand retreats without even seeing the bandits—how can this be!\"", idiomatic: "\"Your Highness commands a hundred thousand men and retreats without even meeting the enemy—how can this be!\"" },
  { zh: "」繹不悅，未幾，因事殺之。", literal: "\" Yi was displeased; before long, on a pretext, he killed him.", idiomatic: "\" Yi was displeased. Before long he killed him on a pretext." },
  { zh: "手造，懿之孫也。", literal: "Shouzao was the grandson of Yi.", idiomatic: "Shouzao was the grandson of Xiao Yi." },
  { zh: "東魏河內民四千餘家，以魏北徐州刺史司馬裔，其鄉里也，相帥歸之。", literal: "More than four thousand households of Henei in Eastern Wei, because Wei Northern Xuzhou Inspector Sima Yi was their home district, led one another in submission to him.", idiomatic: "More than four thousand households of Henei in Eastern Wei, because Northern Xuzhou inspector Sima Yi was a native son, submitted to him in a body." },
  { zh: "丞相泰欲封裔，裔因辭曰：「士大夫遠歸皇化，裔豈能帥之！", literal: "Chief Minister Tai wished to enfeoff Yi; Yi therefore declined, saying: \"Scholar-officials came from afar to submit to imperial transformation—how could Yi lead them!", idiomatic: "Chief minister Tai wished to enfeoff Yi. Yi declined: \"Scholar-officials came from afar to submit to the throne—how could I claim to lead them!" },
  { zh: "賣義士以求榮，非所願也。", literal: "\"Selling righteous men to seek glory is not what I wish.", idiomatic: "\"To sell righteous men for glory is not what I wish." },
  { zh: "侯景運東府米入石頭，既畢，王偉聞荊州軍退，援軍雖多，不相統壹，乃說景曰：「王以人臣舉兵，圍守宮闕，逼辱妃主，殘穢宗廟，擢王之發，不足數罪。", literal: "Hou Jing transported grain from the Eastern Quarter into Shitou; when that was done, Wang Wei heard Jingzhou troops had withdrawn. Though relief armies were many, they were not unified, and he persuaded Jing: \"Your Highness as a subject raised troops, besieged and held the palace gates, forced and shamed consorts and princesses, defiled the ancestral temple, plucked out the king's hair—the crimes cannot all be counted.", idiomatic: "Hou Jing finished moving grain from the Eastern Quarter into Shitou. Wang Wei heard Jingzhou troops had withdrawn. Relief was numerous but disunited, and he urged Jing: \"You raised troops as a subject, besieged the palace, shamed consorts and princesses, defiled the ancestral temple, plucked the king's hair—your crimes are beyond counting." },
  { zh: "今日持此，欲安所容身乎！", literal: "\"Holding this today—where do you think you can find a place to stand!\"", idiomatic: "\"With this on your head, where do you think you can stand!\"" },
  { zh: "背盟而捷，自古多矣，願且觀其變。", literal: "\"Breaking oath yet prospering—since antiquity there have been many; I wish only to watch how things change for now.", idiomatic: "\"Breaking oaths yet prospering—history is full of it. Watch how things change for now." },
  { zh: "」臨賀王正德亦謂景曰：「大功垂就，豈可棄去！", literal: "\" Prince of Linhe Zhengde also said to Jing: \"Great merit is almost complete—how can you abandon it!", idiomatic: "\" Prince Zhengde of Linhe also told Jing: \"Great victory is within reach—how can you walk away!" },
  { zh: "」景遂上啟，陳上十失，且曰：「臣方事睽違，所以冒陳讜直。", literal: "\" Jing then sent up a memorial listing the emperor's ten failures, and said: \"Your servant's affairs are at odds with the throne; therefore I dare present blunt counsel.", idiomatic: "\" Jing then memorialized the emperor with ten failures and wrote: \"My affairs and the throne are at odds; therefore I dare speak bluntly." },
  { zh: "陛下崇飾虛誕，惡聞實錄，以襖怪為嘉禎，以天譴為無咎。", literal: "\"Your Majesty adorns emptiness and falsehood, hates to hear true records, takes omens and monsters as auspicious signs, and treats heaven's punishment as blameless.", idiomatic: "\"Your Majesty worships empty show, hates true records, takes omens for blessings, and treats heaven's punishment as nothing." },
  { zh: "敷演六藝，排擯前儒，王莽之法也。", literal: "\"Expounding the Six Arts while pushing aside former Confucians—this is Wang Mang's way.", idiomatic: "\"Expounding the Six Arts while casting out the old masters—Wang Mang's way." },
  { zh: "以鐵為貨，輕重無常，公孫之制也。", literal: "\"Using iron as currency with weight neither fixed nor constant—this is Gongsun's system.", idiomatic: "\"Iron currency of shifting weight—Gongsun's system." },
  { zh: "爛羊鐫印，朝章鄙雜，更始、趙倫之化也。", literal: "\"Engraving seals for rotten sheep, court regalia base and mixed—this is the transformation of Gengshi and Zhao Lun.", idiomatic: "\"Seals for rotten sheep, court ranks in chaos—the ways of Gengshi and Zhao Lun." },
  { zh: "豫章以所天為血仇，邵陵以父存而冠布，石虎之風也。", literal: "\"Yuzhang takes her husband's killer as blood enemy; Shaoling wears hemp while his father still lives—this is Shi Hu's wind.", idiomatic: "\"Yuzhang treats her husband's killer as blood enemy; Shaoling wears mourning while his father lives—Shi Hu's spirit." },
  { zh: "修建浮圖，百度糜費，使四民饑食妥，笮融、姚興之代也。", literal: "\"Building pagodas, every measure wasted in extravagance, leaving the four classes hungry for food and rest—this is the age of Zha Rong and Yao Xing.", idiomatic: "\"Building pagodas while the realm starves—the age of Zha Rong and Yao Xing." },
  { zh: "」又言：「建康宮室崇侈，陛下唯與主書參斷萬機，政以賄成，諸閹豪盛，眾僧殷實。", literal: "\" He also said: \"Jiankang's palaces are lofty and extravagant; Your Majesty decides the myriad affairs only with chief clerks; government is completed by bribes; eunuchs and magnates flourish; monks and priests are rich and full.", idiomatic: "\" He also wrote: \"Jiankang's palaces are extravagant; Your Majesty decides all affairs only with chief clerks; government runs on bribes; eunuchs and magnates flourish; monks grow fat." },
  { zh: "皇太子珠玉是好，酒色是耽，吐言止於輕薄，賦詠不出《桑中》；", literal: "\"The crown prince loves pearls and jade and is sunk in wine and women; his words stop at the frivolous; his poems never leave 'In the Mulberry Grove';", idiomatic: "\"The crown prince loves jewels and wine and women; his speech is frivolous; his poems never leave 'In the Mulberry Grove';" },
  { zh: "邵陵所在殘破；", literal: "\"Shaoling's domains lie in ruins;", idiomatic: "\"Shaoling's domains lie in ruins;" },
  { zh: "湘東群下貪縱；", literal: "\"Xiangdong's followers are greedy and unrestrained;", idiomatic: "\"Xiangdong's men are greedy and unrestrained;" },
  { zh: "南康、定襄之屬，皆如沐猴而冠耳。", literal: "\"Nankang, Dingxiang, and their kind are all like monkeys dressed in caps.", idiomatic: "\"Nankang, Dingxiang, and their kind are monkeys in caps." },
  { zh: "親為孫侄，位則籓屏，臣至百日，誰肯勤王！", literal: "\"Kin as grandsons and nephews, posts as frontier shields—your servant has been here a hundred days; who would stir to save the throne!", idiomatic: "\"They are your kin and your frontier shields—I have been here a hundred days; who would march to save you!" },
  { zh: "此而靈長，未之有也。", literal: "\"That the realm should endure thus—never has there been such a thing.", idiomatic: "\"That the realm should endure like this—never before." },
  { zh: "昔鬻拳兵諫，王卒改善，今日之舉，復奚罪乎！", literal: "\"In olden days Yuzquan remonstrated with arms and the king at last reformed; today's act—what crime is it again!\"", idiomatic: "\"Yuzquan once remonstrated with arms and the king reformed—what crime is today's act!\"" },
  { zh: "伏願陛下小懲大戒，放讒納忠，使臣無再舉之憂，陛下無嬰城之辱，則萬姓幸甚！", literal: "\"I humbly wish Your Majesty small punishment and great warning, dismiss slander and accept loyalty, so your servant has no fear of raising arms again and Your Majesty has no shame of being besieged—then the myriad people will be greatly fortunate!\"", idiomatic: "\"I beg Your Majesty: punish lightly, warn greatly, cast out slander and take in loyalty, so I need not rise again and you need not endure siege—then the people will be blessed!\"" },
  { zh: "上覽啟，且慚且怒。", literal: "The emperor read the memorial, ashamed and angry together.", idiomatic: "The emperor read the memorial, ashamed and furious." },
  { zh: "三月，丙辰朔，立壇於太極殿前，告天地。", literal: "In the third month, on the first day bingchen, an altar was raised before the Hall of Supreme Pole to announce heaven and earth.", idiomatic: "In the third month, on bingchen, the new moon, they raised an altar before the Hall of Supreme Pole and announced heaven and earth." },
  { zh: "以景違盟，舉烽鼓噪。", literal: "Because Jing violated the oath, beacon fires were raised and drums shouted.", idiomatic: "Because Jing broke the oath, beacons were lit and drums beaten." },
  { zh: "初，閉城之日，男女十餘萬，擐甲者二萬餘人；", literal: "At first, on the day the city was closed, men and women numbered more than a hundred thousand; those who donned armor were more than twenty thousand;", idiomatic: "When the city was first sealed, more than a hundred thousand men and women were inside; more than twenty thousand wore armor;" },
  { zh: "被圍既久，人多身腫氣急，死者什八九，乘城者不滿四千人，率皆羸喘。", literal: "besieged long, many swelled in body and gasped for breath; eight or nine in ten died; those who manned the walls were fewer than four thousand, mostly weak and panting.", idiomatic: "after long siege most bodies swelled and breath failed; eight or nine in ten died. Fewer than four thousand manned the walls, mostly weak and gasping." },
  { zh: "橫屍滿路，不可瘞埋，爛汁滿溝，而眾心猶望外援。", literal: "Corpses lay across the roads, impossible to bury; rotting fluid filled the ditches—yet hearts still hoped for outside relief.", idiomatic: "Corpses choked the roads, too many to bury; rot filled the ditches—yet hearts still hoped for relief from outside." },
  { zh: "柳仲禮唯聚妓妾，置酒作樂，諸將日往請戰，仲禮不許。", literal: "Liu Zhongli only gathered singing girls and concubines, set out wine and made music; generals daily came asking to fight—Zhongli would not allow it.", idiomatic: "Liu Zhongli gathered singing girls and concubines, drank and made music. Generals came daily begging to fight—Zhongli refused." },
  { zh: "安南侯駿說邵陵王綸曰：「城危如此，而都督不救，若萬一不虞，殿下何顏自立於世！", literal: "Marquis Jun of Annan persuaded Prince of Shaoling Lun: \"The city is perilous like this, yet the commander will not rescue it—if by any chance disaster comes, with what face can Your Highness stand in the world!", idiomatic: "Marquis Jun of Annan urged Prince Lun of Shaoling: \"The city is dying and the commander will not save it. If disaster comes, how will you face the world!" },
  { zh: "今宜分軍為三道，出賊不意攻之，可以得志。", literal: "\"Now you should divide the army into three routes and strike where the bandits do not expect—it can succeed.", idiomatic: "\"Split the army three ways and strike where they do not expect—you can still win." },
  { zh: "」綸不從。", literal: "\" Lun did not follow.", idiomatic: "\" Lun would not listen." },
  { zh: "柳津登城謂仲禮曰：「汝君父在難，不能竭力，百世之後，謂汝為何！", literal: "Liu Jin mounted the wall and said to Zhongli: \"Your lord and father are in peril and you cannot exert yourself—a hundred generations hence, what will they call you!", idiomatic: "Liu Jin climbed the wall and told Zhongli: \"Your lord and father are in peril and you will not exert yourself—a hundred generations hence, what will they call you!" },
  { zh: "」仲禮亦不以為意。", literal: "\" Zhongli also paid it no mind.", idiomatic: "\" Zhongli did not care." },
  { zh: "上問策於津，對曰：「陛下有邵陵，臣有仲禮，不忠不孝，賊何由平！", literal: "The emperor asked Jin for counsel; he replied: \"Your Majesty has Shaoling; your servant has Zhongli—disloyal and unfilial—how can the bandits be pacified!", idiomatic: "The emperor asked Jin for counsel. He said: \"Your Majesty has Shaoling; I have Zhongli—disloyal and unfilial—how can bandits be crushed!" },
  { zh: "戊午，南康王會理與羊鴉仁、趙伯超等進營於東府城北，約夜渡軍。", literal: "On wuwu, Prince of Nankang Huili with Yang Yaren, Zhao Bochao, and others advanced camp north of the Eastern Quarter city and agreed to cross troops by night.", idiomatic: "On wuwu, Prince Huili of Nankang with Yang Yaren, Zhao Bochao, and others encamped north of the Eastern Quarter and planned a night crossing." },
  { zh: "既而鴉仁等曉猶未至，景眾覺之。", literal: "Then Yaren and the others at dawn had still not arrived; Jing's host noticed.", idiomatic: "But at dawn Yaren and the others had still not come; Jing's men noticed." },
  { zh: "營未立，景使宋子仙擊之，趙伯超望風退走。", literal: "The camp was not yet set when Jing sent Song Zixian to strike; Zhao Bochao fled at sight of the wind.", idiomatic: "Before the camp was set, Jing sent Song Zixian to attack. Zhao Bochao fled at the first sight of them." },
  { zh: "會理等兵大敗，戰及溺死者五千人。", literal: "Huili's troops were routed; those killed in battle and drowned numbered five thousand.", idiomatic: "Huili's force was routed; five thousand died in battle or drowned." },
  { zh: "景積其首於闕下，以示城中。", literal: "Jing piled their heads below the gate towers to show the city.", idiomatic: "Jing piled their heads beneath the gate towers for the city to see." },
  { zh: "景又使於子悅求和，上使御史中丞沈浚至景所。", literal: "Jing again sent Yu Ziyue to seek peace; the emperor sent Imperial Censor Zhongcheng Shen Jun to Jing's camp.", idiomatic: "Jing sent Yu Ziyue to seek peace again. The emperor sent imperial censor Shen Jun to Jing's camp." },
  { zh: "景實無去志，謂浚曰：「今天時方熱，軍未可動，乞且留京師立效。", literal: "Jing in truth had no mind to leave and said to Jun: \"Heaven's season is just hot; the army cannot move— I beg to stay in the capital for now and prove my worth.", idiomatic: "Jing had no intention of leaving and told Jun: \"The weather is hot; the army cannot move. Let me stay in the capital and prove my worth." },
  { zh: "」浚發憤責之，景不對，橫刀叱之。", literal: "\" Jun in fury rebuked him; Jing did not answer and shouted at him with bared blade.", idiomatic: "\" Jun raged at him. Jing said nothing and shouted at him with blade drawn." },
  { zh: "浚曰：「負恩忘義，違棄詛盟，固天地所不容！", literal: "Jun said: \"Ingratitude and forgetting righteousness, abandoning sworn oaths—surely heaven and earth will not tolerate this!", idiomatic: "Jun said: \"Ingratitude and broken oaths—heaven and earth will not tolerate you!" },
  { zh: "沈浚五十之年，常恐不得死所，何為以死相懼邪！", literal: "\"Shen Jun at fifty years often feared he would not find a place to die—why use death to frighten me!\"", idiomatic: "\"I am fifty and have long feared I would not find a place to die—why threaten me with death!\"" },
  { zh: "」因徑去不顧。", literal: "\" He then went straight away without looking back.", idiomatic: "\" He walked away without looking back." },
  { zh: "景以其忠直，捨之。", literal: "Jing, because of his loyalty and bluntness, let him go.", idiomatic: "Jing, respecting his blunt loyalty, let him go." },
  { zh: "於是景決石闕前水，百道攻城，晝夜不息。", literal: "Thereupon Jing diverted the water before the Stone Gate and attacked the city on a hundred routes, day and night without cease.", idiomatic: "Then Jing diverted the water before the Stone Gate and assaulted the city on a hundred fronts, day and night without pause." },
  { zh: "邵陵世子堅屯太陽門，終日蒲飲，不恤吏士，其書佐董勳、熊曇朗恨之。", literal: "Shaoling Heir Jian garrisoned the Sun Gate, drank and gambled all day, cared nothing for officers and soldiers; his clerks Dong Xun and Xiong Tanlang hated him.", idiomatic: "Shaoling heir Jian held the Sun Gate, drank and gambled all day, and cared nothing for his men. His clerks Dong Xun and Xiong Tanlang hated him." },
  { zh: "丁卯，夜向曉，勳、曇朗於城西北樓引景眾登城，永安侯確力戰，不能卻，乃排闥入啟上云：「城已陷。", literal: "On dingmao, toward dawn in the night, Xun and Tanlang from the northwest tower led Jing's host onto the walls; Marquis Que of Yong'an fought hard but could not drive them back, then burst through the door and reported to the emperor: \"The city has fallen.", idiomatic: "On dingmao, near dawn, Xun and Tanlang led Jing's men onto the walls from the northwest tower. Marquis Que of Yong'an fought hard but could not hold them. He burst in and told the emperor: \"The city has fallen." },
  { zh: "」上安臥不動，曰：「猶可一戰乎？", literal: "\" The emperor lay at rest unmoved and said: \"Can we still fight once?", idiomatic: "\" The emperor lay still and asked: \"Can we still fight?" },
  { zh: "」對曰：「不可。", literal: "\" He answered: \"We cannot.", idiomatic: "\" He answered: \"No." },
  { zh: "」上歎曰：「自我得之，自我失之，亦復何恨！", literal: "\" The emperor sighed: \"I gained it myself, I lose it myself—what regret remains!", idiomatic: "\" The emperor sighed: \"I won it myself and lose it myself—what regret is there!" },
  { zh: "」因謂確曰：「汝速去，語汝父，勿以二宮為念。", literal: "\" Then he said to Que: \"Go quickly; tell your father not to think of the two palaces.", idiomatic: "\" He told Que: \"Go quickly. Tell your father not to worry for us two." },
  { zh: "」因使慰勞在外諸軍。", literal: "\" He then sent word to comfort the armies outside.", idiomatic: "\" He sent word to comfort the armies outside." },
  { zh: "俄而景遣王偉入文德殿奉謁，上命褰簾開戶引偉入，偉拜呈景啟，稱：「為奸佞所蔽，領眾入朝，驚動聖躬，今詣闕待罪。", literal: "Soon Jing sent Wang Wei into the Hall of Cultured Virtue to pay respects; the emperor ordered the curtain lifted and doors opened to admit Wei; Wei bowed and presented Jing's memorial, saying: \"Deceived by wicked flatterers, I led the host into court and disturbed the sage person—now I come to the palace gates to await punishment.", idiomatic: "Soon Jing sent Wang Wei to the Hall of Cultured Virtue. The emperor ordered the curtain raised and doors opened. Wei bowed and presented Jing's memorial: \"Wicked flatterers misled me. I led troops to court and disturbed Your Majesty. I come now to await punishment." },
  { zh: "」上問：「景何在？", literal: "\" The emperor asked: \"Where is Jing?", idiomatic: "\" The emperor asked: \"Where is Jing?" },
  { zh: "可召來。", literal: "\"Summon him.", idiomatic: "\"Summon him." },
  { zh: "」景入見於太極東堂，以甲士五百人自衛。", literal: "\" Jing entered audience at the Eastern Hall of Supreme Pole with five hundred armored men as guard.", idiomatic: "\" Jing came to audience at the Eastern Hall of Supreme Pole with five hundred armored guards." },
  { zh: "景稽顙殿下，典儀引就三公榻。", literal: "Jing knocked his forehead on the hall floor; the master of ceremonies led him to the Three Excellencies' couch.", idiomatic: "Jing kowtowed on the hall floor. The master of ceremonies led him to the three excellencies' couch." },
  { zh: "上神色不變，問曰：「卿在軍中日久，無乃為勞！", literal: "The emperor's expression did not change and he asked: \"You have been long in the army—are you not weary!", idiomatic: "The emperor's face did not change. He asked: \"You have been long in the field—are you not weary!" },
  { zh: "」景不敢仰視，汗流被面。", literal: "\" Jing dared not look up; sweat streamed over his face.", idiomatic: "\" Jing dared not look up. Sweat streamed down his face." },
  { zh: "又曰：「卿何州人，而敢至此，妻子猶在北邪？", literal: "He also asked: \"What province are you from, that you dare come here—are your wife and children still in the north?\"", idiomatic: "He also asked: \"What province are you from, that you dare come here? Are your wife and children still in the north?\"" },
  { zh: "」景皆不能對。", literal: "\" Jing could answer none of it.", idiomatic: "\" Jing could answer nothing." },
  { zh: "任約從旁代對曰：「臣景妻子皆為高氏所屠，唯以一身歸陛下。", literal: "Ren Yue from the side answered for him: \"Your servant Jing's wife and children were all slaughtered by the Gao clan; only with this single body does he return to Your Majesty.", idiomatic: "Ren Yue answered from the side: \"Jing's wife and children were all killed by the Gaos. Only his single body returns to Your Majesty." },
  { zh: "」上又問：「初渡江有幾人？", literal: "\" The emperor again asked: \"When you first crossed the river, how many were there?", idiomatic: "\" The emperor asked again: \"When you first crossed the river, how many were you?" },
  { zh: "」景曰：「千人。", literal: "\" Jing said: \"A thousand.", idiomatic: "\" Jing said: \"A thousand." },
  { zh: "」「圍台城幾人？", literal: "\" \"When you besieged Taicheng, how many?", idiomatic: "\" \"When you besieged Taicheng, how many?" },
  { zh: "」曰：「十萬。", literal: "\" He said: \"A hundred thousand.", idiomatic: "\" He said: \"A hundred thousand." },
  { zh: "」「今有幾人？", literal: "\" \"How many now?", idiomatic: "\" \"How many now?" },
  { zh: "」曰：「率土之內，莫非己有。", literal: "\" He said: \"Within the realm's four seas, all are mine.", idiomatic: "\" He said: \"All beneath heaven is mine." },
  { zh: "」上俯首不言。", literal: "\" The emperor bowed his head and said nothing.", idiomatic: "\" The emperor bowed his head and said nothing." },
  { zh: "景復至永福省見太子，太子亦無懼容。", literal: "Jing again went to Yongfu Palace to see the crown prince; the crown prince also showed no fear.", idiomatic: "Jing went to Yongfu Palace to see the crown prince. The crown prince showed no fear." },
  { zh: "侍衛皆驚散，唯中庶子徐手離、通事舍人陳郡殷不害側侍。", literal: "The guards all fled in alarm; only Palace Companion Xu Shouli and Communications Attendant Yin Buhai of Chen commandery waited at his side.", idiomatic: "The guards fled in panic. Only palace companion Xu Shouli and communications attendant Yin Buhai of Chen waited at his side." },
  { zh: "手離謂景曰：「侯王當以禮見，何得如此！", literal: "Shouli said to Jing: \"The marquis-king should be received with ritual—how can it be like this!", idiomatic: "Shouli told Jing: \"The prince should be received with proper rites—how dare you behave like this!" },
  { zh: "」景乃拜。", literal: "\" Jing then bowed.", idiomatic: "\" Jing then bowed." },
  { zh: "太子與言，又不能對。", literal: "The crown prince spoke with him; again he could not answer.", idiomatic: "The crown prince spoke to him; again he could not answer." },
  { zh: "景退，謂其廂公王僧貴曰：「吾常跨鞍對陳，矢刃交下，而意氣安緩，了無怖心。", literal: "Jing withdrew and said to his aide Wang Senggui: \"I often sat the saddle facing battle, arrows and blades falling together, yet my spirit was calm and slow—I had no fear at all.", idiomatic: "Jing withdrew and told his aide Wang Senggui: \"I have faced battle from the saddle with arrows and blades falling around me, spirit calm, without a trace of fear." },
  { zh: "今見蕭公，使人自懾，豈非天威難犯！", literal: "\"Now seeing Lord Xiao, one is awed of oneself—is this not heaven's majesty hard to violate!", idiomatic: "\"Now seeing Lord Xiao, I am awed within—is this not heaven's majesty!" },
  { zh: "吾不可以再見之。", literal: "\"I cannot see him again.", idiomatic: "\"I cannot face him again." },
  { zh: "」於是悉撤兩宮侍衛，縱兵掠乘輿、服御、宮人皆盡。", literal: "\" Thereupon he removed all guards of both palaces and let soldiers plunder until imperial carriages, regalia, and palace women were all gone.", idiomatic: "\" Then he stripped both palaces of guards and let his soldiers plunder carriages, regalia, and palace women to the last." },
  { zh: "收朝士、王侯送永福省，使王偉守武德殿，於子悅屯太極東堂。", literal: "He gathered court officials and princes and sent them to Yongfu Palace; he made Wang Wei guard the Hall of Martial Virtue and Yu Ziyue encamp at the Eastern Hall of Supreme Pole.", idiomatic: "He gathered court officials and princes into Yongfu Palace, posted Wang Wei at the Hall of Martial Virtue, and Yu Ziyue at the Eastern Hall of Supreme Pole." },
  { zh: "矯詔大赦，自加大都督中外諸軍、錄尚書事。", literal: "He forged an edict of general amnesty and added to himself Grand Commander of All Armies Within and Without and Recorder of Masters of Writing Affairs.", idiomatic: "He forged a general amnesty and made himself grand commander of all armies and recorder of the Masters of Writing." },
  { zh: "建康士民逃難四出。", literal: "Jiankang gentry and commoners fled in all directions.", idiomatic: "Jiankang's people fled in every direction." },
  { zh: "太子洗馬蕭允至京口，端居不行，曰：「死生有命，如何可逃！", literal: "Crown Prince Groom Xiao Yun reached Jingkou, sat properly and would not flee, saying: \"Life and death have their decree—how can one flee!", idiomatic: "Crown prince groom Xiao Yun reached Jingkou, sat still, and would not flee. He said: \"Life and death are fated—how can one flee!" },
  { zh: "禍之所來，皆生於利；", literal: "\"Disaster's coming is all born from profit;", idiomatic: "\"Disaster comes from profit;" },
  { zh: "苟不求利，禍從何生！", literal: "\"if one does not seek profit, from where does disaster arise!\"", idiomatic: "\"seek no profit, and disaster has nowhere to come from!\"" },
  { zh: "己巳，景遣石城公大款以詔命解外援軍。", literal: "On jisi, Jing sent Prince of Shicheng Dakuan with forged edict orders to dismiss the outside relief armies.", idiomatic: "On jisi Jing sent Prince Dakuan of Shicheng with forged orders to dismiss the relief armies." },
  { zh: "柳仲禮召諸將議之，邵陵王綸曰：「今日之命，委之將軍。", literal: "Liu Zhongli summoned the generals to discuss; Prince of Shaoling Lun said: \"Today's command rests with the general.", idiomatic: "Liu Zhongli called the generals to council. Prince Lun of Shaoling said: \"Today's decision rests with you, general." },
  { zh: "」仲禮熟視不對。", literal: "\" Zhongli stared fixedly and did not answer.", idiomatic: "\" Zhongli stared and said nothing." },
  { zh: "裴之高、王僧辯曰：「將軍擁眾百萬，致宮闕淪沒，正當悉力決戰，何所多言！", literal: "Pei Zhigao and Wang Senbian said: \"The general holds a host of a million yet let the palace gates fall—he should now fight with all strength; what need for so much talk!", idiomatic: "Pei Zhigao and Wang Senbian said: \"You command a million men and let the palace fall—you should fight with everything you have. Why so many words!" },
  { zh: "」仲禮竟無一言，諸軍乃隨方各散。", literal: "\" Zhongli in the end said not a word; the armies then dispersed each to its own direction.", idiomatic: "\" Zhongli said nothing. The armies dispersed each to its own place." },
  { zh: "南兗州刺史臨成公大連、湘東世子方等、鄱陽世子嗣、北兗州刺史湘潭侯退、吳郡太守袁君正、晉陵太守陸經等各還本鎮。", literal: "Southern Yanzhou Inspector Prince of Lincheng Dalian, Xiangdong Heir Fangdeng, Poyang Heir Si, Northern Yanzhou Inspector Marquis Tui of Xiangtan, Wu Commandery Administrator Yuan Junzheng, and Jinling Administrator Lu Jing each returned to their own posts.", idiomatic: "Southern Yanzhou inspector Prince Dalian of Lincheng, Xiangdong heir Fangdeng, Poyang heir Si, Northern Yanzhou inspector Marquis Tui of Xiangtan, Wu administrator Yuan Junzheng, and Jinling administrator Lu Jing each returned to their posts." },
  { zh: "君正，昂之子也。", literal: "Junzheng was the son of Ang.", idiomatic: "Junzheng was the son of Yuan Ang." },
  { zh: "邵陵王綸奔會稽。", literal: "Prince of Shaoling Lun fled to Kuaiji.", idiomatic: "Prince Lun of Shaoling fled to Kuaiji." },
  { zh: "仲禮及弟敬禮、羊鴉仁、王僧辯、趙伯超並開營降，軍士莫不歎憤。", literal: "Zhongli and his younger brother Jingli, Yang Yaren, Wang Senbian, and Zhao Bochao all opened camp and surrendered; the soldiers none failed to sigh in anger.", idiomatic: "Liu Zhongli and his younger brother Jingli, Yang Yaren, Wang Senbian, and Zhao Bochao all opened camp and surrendered; the soldiers groaned with fury." },
  { zh: "仲禮等入城，先拜景而後見上；", literal: "Zhongli and the others entered the city, first bowing to Jing and only then seeing the emperor.", idiomatic: "Zhongli and the others entered the city, bowing first to Hou Jing and only then presenting themselves to the emperor." },
  { zh: "上不與言。", literal: "The emperor did not speak with them.", idiomatic: "The emperor would not speak to them." },
  { zh: "仲禮見父津，津慟哭曰：「汝非我子，何勞相見！", literal: "Zhongli saw his father Jin; Jin wailed and said, \"You are not my son—why trouble yourself to meet me!", idiomatic: "Zhongli went to see his father Liu Jin; Jin wailed and said, \"You are not my son—why bother to meet me!" },
  { zh: "」湘東王繹使全威將軍會稽王琳送米二十萬石以饋軍，至姑孰，聞台城陷，沉米於江而還。", literal: "\" Prince Yi of Xiangdong sent General Quanwei Prince Lin of Kuaiji with two hundred thousand shi of rice to supply the army; reaching Gushu, he heard the capital had fallen, sank the rice in the river, and returned.", idiomatic: "\" Prince Yi of Xiangdong sent General Quanwei, Prince Lin of Kuaiji, with two hundred thousand shi of rice to supply the army; reaching Gushu, he heard the capital had fallen, dumped the rice into the river, and turned back." },
  { zh: "景命燒台內積屍，病篤未絕者，亦聚而焚之。", literal: "Jing ordered the piled corpses within the capital burned; those still lingering in critical illness were also gathered and incinerated.", idiomatic: "Hou Jing ordered the piled corpses within the capital burned; even those still clinging to life in their final illness were gathered and thrown on the pyres." },
  { zh: "庚午，詔征鎮牧守可復本任。", literal: "On gengwu, an edict declared that frontier commanders, garrison leaders, and prefects might resume their original posts.", idiomatic: "On gengwu, an edict declared that frontier commanders, garrison leaders, and prefects might resume their original posts." },
  { zh: "景留柳敬禮、羊鴉仁，而遣柳仲禮歸司州，王僧辯歸竟陵。", literal: "Jing kept Liu Jingli and Yang Yaren, but sent Liu Zhongli back to Si province and Wang Senbian back to Jingling.", idiomatic: "Hou Jing kept Liu Jingli and Yang Yaren, but sent Liu Zhongli back to Si province and Wang Senbian back to Jingling." },
  { zh: "初，臨賀王正德與景約，平城之日，不得全二宮。", literal: "Earlier, Prince Zhengde of Linhe had agreed with Jing that on the day the city was taken, neither of the two palaces would be spared.", idiomatic: "Earlier, Prince Zhengde of Linhe had struck a bargain with Hou Jing: on the day the city fell, neither the emperor nor the crown prince would be left alive." },
  { zh: "及城開，正德帥眾揮刀欲入，景先使其徒守門，故正德不果入。", literal: "When the city opened, Zhengde led his men with drawn blades intending to enter; Jing had already posted his followers to guard the gates, so Zhengde could not get in.", idiomatic: "When the city fell, Zhengde led his men in with blades drawn; Hou Jing had already posted guards at the gates, and Zhengde never got inside." },
  { zh: "景更以正德為侍中、大司馬，百官皆復舊職。", literal: "Jing further made Zhengde Palace Attendant and Grand Marshal; all officials resumed their former offices.", idiomatic: "Hou Jing made Zhengde Palace Attendant and Grand Marshal anyway, and all officials resumed their former offices." },
  { zh: "正德入見上，拜且泣。", literal: "Zhengde entered to see the emperor, bowing and weeping.", idiomatic: "Zhengde entered to see the emperor, bowing and weeping." },
  { zh: "上曰：「啜其泣矣，何嗟及矣！", literal: "The emperor said, \"You have already wept your fill—what use is regret now!", idiomatic: "The emperor said, \"You have already wept your fill—what use is regret now!" },
  { zh: "秦郡、陽平、盱眙三郡皆降景，景改陽平為北滄州，改秦郡為西兗州。", literal: "The three commanderies of Qin, Yangping, and Xuyi all surrendered to Jing; Jing renamed Yangping North Cang province and Qin West Yan province.", idiomatic: "The three commanderies of Qin, Yangping, and Xuyi all surrendered to Hou Jing, who renamed Yangping North Cang province and Qin West Yan province." },
  { zh: "東徐州刺史湛海珍、北青州刺史王奉伯、淮陽太守王瑜，並以地降東魏。", literal: "Eastern Xuzhou Inspector Zhan Haizhen, Northern Qing Inspector Wang Fengbo, and Huaiyang Administrator Wang Yu all surrendered their territories to Eastern Wei.", idiomatic: "Eastern Xuzhou Inspector Zhan Haizhen, Northern Qing Inspector Wang Fengbo, and Huaiyang Administrator Wang Yu all surrendered their territories to Eastern Wei." },
  { zh: "青州刺史明少遐、山陽太守蕭鄰棄城走，東魏據其地。", literal: "Qing Inspector Ming Shaoxia and Shanyang Administrator Xiao Lin abandoned their cities and fled; Eastern Wei seized the territory.", idiomatic: "Qing Inspector Ming Shaoxia and Shanyang Administrator Xiao Lin abandoned their cities and fled; Eastern Wei seized the territory." },
  { zh: "侯景以儀同三司蕭邕為南徐州刺史，代西昌侯淵藻鎮京口。", literal: "Hou Jing made Xiao Yong, Equal in Honor to the Three Dukes, Inspector of South Xuzhou, replacing Marquis Yuanzao of Xichang to garrison Jingkou.", idiomatic: "Hou Jing made Xiao Yong, Equal in Honor to the Three Dukes, Inspector of South Xuzhou, replacing Marquis Yuanzao of Xichang to garrison Jingkou." },
  { zh: "又遣其將徐相攻晉陵，陸經以郡降之。", literal: "He also sent his general Xu Xiang to attack Jinling; Lu Jing surrendered the commandery to him.", idiomatic: "He also sent his general Xu Xiang to attack Jinling; Lu Jing surrendered the commandery." },
  { zh: "初，上以河東王譽為湘州刺史，徙湘州刺史張纘為雍州刺史，代岳陽王察。", literal: "Earlier, the emperor had made Prince Yu of Hedong Inspector of Xiangzhou, transferred Xiangzhou Inspector Zhang Zuan to be Inspector of Yongzhou, and replaced Prince Cha of Yueyang.", idiomatic: "Earlier, the emperor had made Prince Yu of Hedong Inspector of Xiangzhou, transferred Xiangzhou Inspector Zhang Zuan to Yongzhou, and replaced Prince Cha of Yueyang." },
  { zh: "纘恃其才望，輕譽少年，迎候有闕。", literal: "Zuan relied on his talent and reputation, looked down on the young Yu, and was deficient in welcoming him.", idiomatic: "Zuan, confident in his talent and reputation, looked down on the young Yu and failed to receive him properly." },
  { zh: "譽至，檢括州府付度事，留纘不遣；", literal: "When Yu arrived, he audited the prefecture and treasury accounts and kept Zuan from leaving.", idiomatic: "When Yu arrived, he audited the prefecture and treasury accounts and kept Zuan from leaving." },
  { zh: "聞侯景作亂，頗陵蹙纘。", literal: "On hearing Hou Jing's rebellion, he treated Zuan with considerable harshness.", idiomatic: "On hearing of Hou Jing's rebellion, he treated Zuan with open contempt." },
  { zh: "纘恐為所害，輕舟夜遁，將之雍部，復慮察拒之。", literal: "Zuan feared he would be killed, fled by light boat at night, intending to go to Yong province, but again feared Cha would reject him.", idiomatic: "Zuan feared for his life, fled by light boat in the night toward Yong province, then feared Cha would turn him away." },
  { zh: "纘與湘東王繹有舊，欲因之以殺譽兄弟，乃如江陵。", literal: "Zuan had old ties with Prince Yi of Xiangdong and wished to use him to kill Yu and his brothers, so he went to Jiangling.", idiomatic: "Zuan had old ties with Prince Yi of Xiangdong and hoped to use him to destroy Yu and his brothers, so he went to Jiangling." },
  { zh: "及台城陷，諸王各還州鎮，譽自湖口歸湘州。", literal: "When the capital fell, the princes each returned to their posts; Yu came back to Xiangzhou from Hukou.", idiomatic: "When the capital fell, the princes each returned to their posts; Yu came back to Xiangzhou from Hukou." },
  { zh: "桂陽王慥以荊州督府留軍江陵，欲待繹至拜謁，乃還信州。", literal: "Prince Hao of Guiyang, holding the Jingzhou supervisory office, left troops at Jiangling, intending to wait until Yi arrived to pay respects before returning to Xin province.", idiomatic: "Prince Hao of Guiyang, holding the Jingzhou supervisory office, left troops at Jiangling, intending to wait until Yi arrived to pay his respects before returning to Xin province." },
  { zh: "纘遺繹書曰：「河東戴檣上水，欲襲江陵，岳陽在雍，共謀不逞。", literal: "Zuan sent Yi a letter saying, \"Hedong has raised sails upstream, intending to strike Jiangling; Yueyang is in Yong, and they are plotting together without success.", idiomatic: "Zuan wrote to Yi: \"Hedong has raised sails upstream, intending to strike Jiangling; Yueyang is in Yong, and they are plotting together without success." },
  { zh: "」江陵遊軍主朱榮亦遣使告繹云：「桂陽留此，欲應譽、察。", literal: "\" Patrol commander Zhu Rong of Jiangling also sent a messenger telling Yi, \"Guiyang remains here, intending to coordinate with Yu and Cha.", idiomatic: "\" Patrol commander Zhu Rong of Jiangling also sent word: \"Guiyang remains here, intending to coordinate with Yu and Cha." },
  { zh: "」繹懼，鑿船，沉米，斬纜，自蠻中步道馳歸江陵，囚慥，殺之。", literal: "\" Yi was afraid; he scuttled boats, sank rice, cut mooring lines, and raced back to Jiangling by footpaths through the barbarian country, imprisoned Hao, and killed him.", idiomatic: "\" Yi panicked; he scuttled boats, dumped rice into the river, cut mooring lines, and raced back to Jiangling by footpaths through the hill country, then imprisoned Hao and killed him." },
  { zh: "侯景以前臨江太守董紹先為江北行台，使繼上手敕，召南兗州刺史南康王會理。", literal: "Hou Jing made former Linjiang Administrator Dong Shaoxian Northern River Mobile Headquarters, had him carry on the emperor's handwritten orders, and summoned South Yanzhou Inspector Prince Huili of Nankang.", idiomatic: "Hou Jing made former Linjiang Administrator Dong Shaoxian Northern River Mobile Headquarters, had him carry forged imperial orders, and summoned South Yanzhou Inspector Prince Huili of Nankang." },
  { zh: "壬午，紹先至廣陵，眾不滿二百，皆積日饑疲。", literal: "On renwu, Shaoxian reached Guangling with fewer than two hundred men, all hungry and exhausted from many days.", idiomatic: "On renwu, Shaoxian reached Guangling with fewer than two hundred men, all hungry and exhausted from many days on the road." },
  { zh: "會理士馬甚盛，僚佐說會理曰：「景已陷京邑，欲先除諸籓，然後篡位。", literal: "Huili's troops and horses were very strong; his staff urged him, saying, \"Jing has already taken the capital; he intends first to eliminate the princes, then usurp the throne.", idiomatic: "Huili's forces were strong; his staff urged him, \"Hou Jing has already taken the capital; he intends first to eliminate the princes, then seize the throne." },
  { zh: "若四方拒絕，立當潰敗，奈何委全州之地以資寇手！", literal: "If the four quarters refuse him, he will quickly collapse—how can you hand over an entire province to the enemy!", idiomatic: "If the four quarters refuse him, he will quickly collapse—how can you hand an entire province to the enemy!" },
  { zh: "不如殺紹先，發兵固守，與魏連和，以待其變。", literal: "Better kill Shaoxian, raise troops and hold firm, ally with Wei, and wait for events to turn.", idiomatic: "Better kill Shaoxian, raise troops and hold firm, ally with Wei, and wait for events to turn." },
  { zh: "」會理素懦，即以城授之。", literal: "\" Huili was by nature timid and surrendered the city at once.", idiomatic: "\" Huili was by nature timid and surrendered the city at once." },
  { zh: "紹先既入，眾莫敢動。", literal: "Once Shaoxian entered, none dared move.", idiomatic: "Once Shaoxian entered, none dared resist." },
  { zh: "會理弟通理請先還建康，謂其姊曰：「事既如此，豈可闔家受斃！", literal: "Huili's younger brother Tongli asked to return to Jiankang first and told his elder sister, \"Matters being as they are, how can the whole family wait to be slaughtered!", idiomatic: "Huili's younger brother Tongli asked to return to Jiankang first and told his elder sister, \"Matters being as they are, how can the whole family wait to be slaughtered!" },
  { zh: "前途亦思立效，但未知天命如何耳。", literal: "I still hope to serve usefully ahead, but who knows what fate holds.", idiomatic: "I still hope to serve usefully ahead, but who knows what fate holds." },
  { zh: "」紹先悉收廣陵文武部曲、鎧仗、金帛，遣會理單馬還建康。", literal: "\" Shaoxian seized all Guangling's civil and military retainers, armor, weapons, gold, and silk, and sent Huili back alone on horseback to Jiankang.", idiomatic: "\" Shaoxian seized all Guangling's civil and military retainers, armor, weapons, gold, and silk, and sent Huili back alone on horseback to Jiankang." },
  { zh: "湘潭侯退與北兗州刺史定襄侯祗出奔東魏。", literal: "Marquis Tui of Xiangtan and North Yanzhou Inspector Marquis Zhi of Dingxiang fled to Eastern Wei.", idiomatic: "Marquis Tui of Xiangtan and North Yanzhou Inspector Marquis Zhi of Dingxiang fled to Eastern Wei." },
  { zh: "侯景以蕭弄璋為北兗州刺史，州民發兵拒之；", literal: "Hou Jing made Xiao Nongzhang Inspector of North Yanzhou; the people of the province raised troops to resist.", idiomatic: "Hou Jing made Xiao Nongzhang Inspector of North Yanzhou; the people of the province raised troops to resist." },
  { zh: "景遣直閣將軍羊海將兵助之，海以其眾降東魏，東魏遂據淮陰。", literal: "Jing sent Direct Attendant General Yang Hai with troops to assist; Hai surrendered his force to Eastern Wei, and Eastern Wei then held Huaiyin.", idiomatic: "Hou Jing sent Direct Attendant General Yang Hai with troops to assist; Hai surrendered his force to Eastern Wei, and Eastern Wei seized Huaiyin." },
  { zh: "祗，偉之子也。", literal: "Zhi was Wei's son.", idiomatic: "Zhi was Wei's son." },
  { zh: "癸未，侯景遣於子悅等將羸兵數百東略吳郡。", literal: "On guimwei, Hou Jing sent Yu Ziyue and others with several hundred weak troops east to raid Wu commandery.", idiomatic: "On guimwei, Hou Jing sent Yu Ziyue and others with several hundred weak troops east to raid Wu commandery." },
  { zh: "新城戍主戴僧逖有精甲五千，說太守袁君正曰：「賊今乏食，台中所得，不支一旬。", literal: "Garrison commander Dai Sengti of Xincheng had five thousand fine armored men and urged Administrator Yuan Junzheng, saying, \"The rebels now lack food; what the capital has will not last ten days.", idiomatic: "Garrison commander Dai Sengti of Xincheng had five thousand fine armored men and urged Administrator Yuan Junzheng: \"The rebels now lack food; what the capital has will not last ten days." },
  { zh: "若閉關拒守，立可餓死。", literal: "If we shut the passes and hold out, they can be starved to death at once.", idiomatic: "If we shut the passes and hold out, we can starve them to death." },
  { zh: "」土豪陸映公等恐不能勝而資產被掠，皆勸君正迎之。", literal: "\" Local magnates such as Lu Yinggong, fearing they could not win and their property would be plundered, all urged Junzheng to welcome the rebels.", idiomatic: "\" Local magnates such as Lu Yinggong, fearing defeat and plunder, all urged Junzheng to welcome the rebels." },
  { zh: "君正素怯，載米及牛酒郊迎。", literal: "Junzheng was by nature timid; he loaded rice, cattle, and wine and went out to the suburbs to welcome them.", idiomatic: "Junzheng was by nature timid; he loaded rice, cattle, and wine and went out to the suburbs to welcome them." },
  { zh: "子悅執君正，掠奪財物、子女，東人皆立堡拒之。", literal: "Ziyue seized Junzheng and plundered goods and women; the people of the east all built fortresses to resist.", idiomatic: "Ziyue seized Junzheng and plundered goods and women; the people of the east all built fortresses to resist." },
  { zh: "景又以任約為南道行台，鎮姑孰。", literal: "Jing also made Ren Yue Southern Route Mobile Headquarters and stationed him at Gushu.", idiomatic: "Hou Jing also made Ren Yue Southern Route Mobile Headquarters and stationed him at Gushu." },
  { zh: "夏，四月，湘東世子方等至江陵，湘東王繹始知台城不守，命於江陵四旁七里樹木為柵，掘塹三重而守之。", literal: "In summer, the fourth month, the Xiangdong heir Fangdeng reached Jiangling; Prince Yi of Xiangdong only then learned the capital had not held; he ordered trees felled for palisades within seven li on all sides of Jiangling and triple ditches dug for defense.", idiomatic: "In summer, the fourth month, the Xiangdong heir Fangdeng reached Jiangling; Prince Yi of Xiangdong only then learned the capital had fallen; he ordered palisades built within seven li on all sides of Jiangling and triple ditches dug for defense." },
  { zh: "東魏高岳等攻魏穎川，不克。", literal: "Gao Yue and others of Eastern Wei attacked Yingchuan in Wei but could not take it.", idiomatic: "Gao Yue and others of Eastern Wei attacked Yingchuan in Western Wei but could not take it." },
  { zh: "大將軍澄益兵助之，道路相繼，逾年猶不下。", literal: "Grand General Cheng sent more troops to assist; they came in an unbroken stream on the roads, yet after more than a year the city still had not fallen.", idiomatic: "Grand General Gao Cheng sent more troops; they came in an unbroken stream on the roads, yet after more than a year the city still had not fallen." },
  { zh: "山鹿忠武公劉豐生建策，堰洧水以灌之，城多崩頹，岳悉眾分休迭進。", literal: "Liu Fengsheng, Duke of Zhongwu of Shanlu, proposed building a dam on the Wei River to flood the city; much of the wall collapsed; Yue divided his entire force into shifts for rest and attack in rotation.", idiomatic: "Liu Fengsheng, Duke of Zhongwu of Shanlu, proposed damming the Wei River to flood the city; much of the wall collapsed; Yue divided his entire force into rotating shifts for rest and assault." },
  { zh: "王思政身當矢石，與士卒同勞苦，城中泉湧，懸釜而炊。", literal: "Wang Sizheng placed himself in the path of arrows and stones, sharing hardship with the soldiers; springs gushed within the city, and they hung cauldrons to cook.", idiomatic: "Wang Sizheng placed himself in the path of arrows and stones, sharing hardship with the soldiers; springs gushed within the city, and they hung cauldrons over them to cook." },
  { zh: "太師泰遣大將軍趙貴督東南諸州兵救之，自長社以北，皆為陂澤，兵至穰，不得前。", literal: "Grand Preceptor Tai sent Grand General Zhao Gui to command southeastern provincial troops to the rescue; from north of Changshe onward all became marshland, and the army reached Xiang but could not advance.", idiomatic: "Grand Preceptor Yuwen Tai sent Grand General Zhao Gui to command southeastern provincial troops to the rescue; from north of Changshe onward all became marshland, and the army reached Xiang but could not advance." },
  { zh: "東魏人使善射者乘大艦臨城射之，城垂陷；", literal: "The Eastern Wei men had skilled archers aboard large ships shoot at the city from close range; the city was near collapse.", idiomatic: "Eastern Wei put skilled archers aboard large ships to shoot at the city from close range; the city was near collapse." },
  { zh: "燕郡景惠公慕容紹宗與劉豐生臨堰視之，見東北塵起，同入艦坐避之。", literal: "Murong Shaozong, Duke of Jinghui of Yanz commandery, and Liu Fengsheng came to the dam to observe; seeing dust rise in the northeast, they both entered a ship and sat to avoid it.", idiomatic: "Murong Shaozong, Duke of Jinghui of Yanz commandery, and Liu Fengsheng came to the dam to observe; seeing dust rise in the northeast, they both boarded a ship to take shelter." },
  { zh: "俄而暴風至，遠近晦冥，纜斷，飄船徑向城；", literal: "Soon a violent wind came; near and far turned dark; mooring lines snapped; the drifting ship headed straight for the city.", idiomatic: "Soon a violent wind came; near and far turned dark; mooring lines snapped; the drifting ship headed straight for the city." },
  { zh: "城上人以長鉤牽船，弓弩亂髮，紹宗赴水溺死，豐生游上，向土山，城上人射殺之。", literal: "Men on the wall hooked the ship with long poles; bows and crossbows fired in disorder; Shaozong threw himself into the water and drowned; Fengsheng swam ashore toward an earthen hill and was shot dead by men on the wall.", idiomatic: "Men on the wall hooked the ship with long poles; bows and crossbows fired in a storm; Shaozong threw himself into the water and drowned; Fengsheng swam ashore toward an earthen hill and was shot dead by the defenders." },
  { zh: "甲辰，東魏進大將軍勃海王澄位相國，封齊王，加殊禮。", literal: "On jiachen, Eastern Wei promoted Grand General Cheng, Prince of Bohai, to Chancellor of State, enfeoffed him as Prince of Qi, and granted extraordinary honors.", idiomatic: "On jiachen, Eastern Wei promoted Grand General Gao Cheng, Prince of Bohai, to Chancellor of State, enfeoffed him as Prince of Qi, and granted extraordinary honors." },
  { zh: "丁未，澄入朝於鄴，固辭；", literal: "On dingwei, Cheng entered court at Ye and firmly declined.", idiomatic: "On dingwei, Cheng entered court at Ye and firmly declined." },
  { zh: "不許。", literal: "They would not permit it.", idiomatic: "They would not permit it." },
  { zh: "澄召將佐密議之，皆勸澄宜膺朝命，獨散騎常侍陳元康以為未可，澄由是嫌之。", literal: "Cheng summoned his generals and aides for secret counsel; all urged him to accept the court's command; only Direct Attendant Chen Yuankang thought it premature, and Cheng therefore came to dislike him.", idiomatic: "Cheng summoned his generals and aides for secret counsel; all urged him to accept the court's command; only Direct Attendant Chen Yuankang thought it premature, and Cheng therefore came to dislike him." },
  { zh: "崔暹乃薦陸元規為大行台郎以分元康之權。", literal: "Cui Xian then recommended Lu Yuangui as an officer of the Grand Mobile Headquarters to divide Yuankang's authority.", idiomatic: "Cui Xian then recommended Lu Yuangui as an officer of the Grand Mobile Headquarters to divide Yuankang's authority." },
  { zh: "湘東王繹之入援也，令所督諸州皆發兵，雍州刺史岳陽王察遣府司馬劉方貴將兵出漢口；", literal: "When Prince Yi of Xiangdong marched to the rescue, he ordered all provinces under his command to raise troops; Yongzhou Inspector Prince Cha of Yueyang sent his chief administrator Liu Fanggui with troops out from Hankou.", idiomatic: "When Prince Yi of Xiangdong marched to the rescue, he ordered all provinces under his command to raise troops; Yongzhou Inspector Prince Cha of Yueyang sent his chief administrator Liu Fanggui with troops out from Hankou." },
  { zh: "繹召察使自行，察不從。", literal: "Yi summoned Cha to come in person; Cha refused.", idiomatic: "Yi summoned Cha to come in person; Cha refused." },
  { zh: "方貴潛與繹相知，謀襲襄陽，未發；", literal: "Fanggui secretly communicated with Yi and plotted to strike Xiangyang, but had not yet acted.", idiomatic: "Fanggui secretly communicated with Yi and plotted to strike Xiangyang, but had not yet acted." },
  { zh: "會察以它事召方貴，方貴以為謀洩，遂據樊城拒命，察遣軍攻之。", literal: "Just then Cha summoned Fanggui on another matter; Fanggui thought the plot had leaked, seized Fancheng and defied orders; Cha sent troops to attack.", idiomatic: "Just then Cha summoned Fanggui on another matter; Fanggui thought the plot had leaked, seized Fancheng and defied orders; Cha sent troops to attack." },
  { zh: "繹厚資遣張纘使赴鎮，纘至大堤，察已拔樊城，斬方貴。", literal: "Yi richly supplied Zhang Zuan and sent him to take up his post; Zuan reached Dadi; Cha had already taken Fancheng and beheaded Fanggui.", idiomatic: "Yi richly supplied Zhang Zuan and sent him to take up his post; Zuan reached Dadi; Cha had already taken Fancheng and beheaded Fanggui." },
  { zh: "纘至襄陽，察推遷未去，但以城西白馬寺處之；", literal: "Zuan reached Xiangyang; Cha put off the transfer and did not leave, lodging Zuan only at White Horse Temple west of the city.", idiomatic: "Zuan reached Xiangyang; Cha put off the transfer and did not leave, lodging Zuan only at White Horse Temple west of the city." },
  { zh: "察猶總軍府之政，聞台城陷，遂不受代。", literal: "Cha still controlled military affairs at headquarters; on hearing the capital had fallen, he refused to be replaced.", idiomatic: "Cha still controlled military affairs at headquarters; on hearing the capital had fallen, he refused to be replaced." },
  { zh: "助防杜岸紿纘曰：「觀岳陽勢不容使君，不如且往西山以避禍。", literal: "Assistant Defender Du An deceived Zuan, saying, \"Judging Yueyang's posture, he will not tolerate you, my lord; better go for now to the western hills to escape disaster.", idiomatic: "Assistant Defender Du An deceived Zuan: \"Judging Yueyang's posture, he will not tolerate you; better go for now to the western hills to escape disaster." },
  { zh: "」岸既襄陽豪族，兄弟九人，皆以驍勇著名。", literal: "\" An was of a powerful Xiangyang clan; nine brothers, all famed for fierce courage.", idiomatic: "\" An was of a powerful Xiangyang clan; nine brothers, all famed for fierce courage." },
  { zh: "纘乃與岸結盟，著婦人衣，乘青布輿，逃入西山。", literal: "Zuan then allied with An, put on women's clothes, rode in a blue-cloth carriage, and fled into the western hills.", idiomatic: "Zuan then allied with An, put on women's clothes, rode in a blue-cloth carriage, and fled into the western hills." },
  { zh: "察使岸將兵追擒之，纘乞為沙門，更名法纘，察許之。", literal: "Cha had An lead troops in pursuit and capture him; Zuan begged to become a monk, changed his name to Fazuan, and Cha consented.", idiomatic: "Cha had An lead troops in pursuit and capture him; Zuan begged to become a monk, changed his name to Fazuan, and Cha consented." },
  { zh: "荊州長史王沖等上箋於湘東王繹，請以太尉、都督中外諸軍事承製主盟，繹不許。", literal: "Jingzhou Chief Administrator Wang Chong and others submitted a memorial to Prince Yi of Xiangdong, asking him to serve as Grand Commandant, Commander of All Forces Inside and Outside, assume regency, and lead the alliance; Yi refused.", idiomatic: "Jingzhou Chief Administrator Wang Chong and others submitted a memorial to Prince Yi of Xiangdong, asking him to serve as Grand Commandant, Commander of All Forces Inside and Outside, assume regency, and lead the alliance; Yi refused." },
  { zh: "丙辰，又請以司空主盟，亦不許。", literal: "On bingchen, they again asked him to lead the alliance as Minister of Works; again he refused.", idiomatic: "On bingchen, they again asked him to lead the alliance as Minister of Works; again he refused." },
  { zh: "上雖外為侯景所制，而內甚不平。", literal: "Though outwardly controlled by Hou Jing, inwardly the emperor was deeply resentful.", idiomatic: "Though outwardly controlled by Hou Jing, inwardly the emperor was deeply resentful." },
  { zh: "景欲以宋子仙為司空，上曰：「調和陰陽，安用此物！", literal: "Jing wished to make Song Zixian Minister of Works; the emperor said, \"Harmonizing yin and yang—what use is there for such a creature!", idiomatic: "Hou Jing wished to make Song Zixian Minister of Works; the emperor said, \"Harmonizing yin and yang—what use is there for such a creature!" },
  { zh: "」景又請以其黨二人為便殿主帥，上不許。", literal: "\" Jing again asked that two of his partisans be made commanders of the side halls; the emperor refused.", idiomatic: "\" Hou Jing again asked that two of his partisans be made commanders of the side halls; the emperor refused." },
  { zh: "景不能強，心甚憚之。", literal: "Jing could not force the issue and inwardly feared him greatly.", idiomatic: "Hou Jing could not force the issue and inwardly feared him greatly." },
  { zh: "太子入，泣諫，上曰：「誰令汝來！", literal: "The crown prince entered and remonstrated through tears; the emperor said, \"Who told you to come!", idiomatic: "The crown prince entered and remonstrated through tears; the emperor said, \"Who told you to come!" },
  { zh: "若社稷有靈，猶當克復；", literal: "If the altars of state have spirit, we may yet recover;", idiomatic: "If the altars of state have spirit, we may yet recover;" },
  { zh: "如其不然，何事流涕！", literal: "if not, what use are tears!", idiomatic: "if not, what use are tears!" },
  { zh: "」景使其軍士入直省中，或驅驢馬，帶弓刀，出入宮庭，上怪而問之，直閤將軍周石珍對曰：「侯丞相甲士。", literal: "\" Jing had his soldiers enter duty in the Secretariat; some drove donkeys and horses, carrying bows and blades, passing in and out of the palace grounds; the emperor wondered and asked; Direct Attendant General Zhou Shizhen answered, \"Chancellor Hou's armored men.", idiomatic: "\" Hou Jing had his soldiers enter duty in the Secretariat; some drove donkeys and horses, carrying bows and blades, passing in and out of the palace grounds; the emperor wondered and asked; Direct Attendant General Zhou Shizhen answered, \"Chancellor Hou's armored men." },
  { zh: "」上大怒，叱石珍曰：「是侯景，何謂丞相！", literal: "\" The emperor was greatly angered and shouted at Shizhen, \"That is Hou Jing—what do you mean, chancellor!", idiomatic: "\" The emperor was greatly angered and shouted at Shizhen, \"That is Hou Jing—what do you mean, chancellor!" },
  { zh: "」左右皆懼。", literal: "\" Those around him were all afraid.", idiomatic: "\" Those around him were all afraid." },
  { zh: "是後上所求多不遂志，飲膳亦為所裁節，憂憤成疾。", literal: "After this the emperor's requests mostly went unfulfilled; his food and drink were also curtailed; grief and anger became illness.", idiomatic: "After this the emperor's requests mostly went unfulfilled; his food and drink were also curtailed; grief and anger became illness." },
  { zh: "太子以幼子大圜屬湘東王繹，並剪爪發以寄之。", literal: "The crown prince entrusted his young son Dayuan to Prince Yi of Xiangdong and also sent clipped fingernails and hair.", idiomatic: "The crown prince entrusted his young son Dayuan to Prince Yi of Xiangdong and also sent clipped fingernails and hair as tokens." },
  { zh: "五月，丙辰，上臥淨居殿，口苦，索蜜不得，再曰：「荷！", literal: "In the fifth month, on bingchen, the emperor lay ill in the Hall of Pure Dwelling; his mouth was bitter; he asked for honey and could not obtain it; twice he said, \"Bitter!", idiomatic: "In the fifth month, on bingchen, the emperor lay ill in the Hall of Pure Dwelling; his mouth was bitter; he asked for honey and could not obtain it; twice he said, \"Bitter!" },
  { zh: "荷！", literal: "Bitter!", idiomatic: "Bitter!" },
  { zh: "」遂殂。", literal: "\" Then he died.", idiomatic: "\" Then he died." },
  { zh: "年八十六。", literal: "He was eighty-six.", idiomatic: "He was eighty-six." },
  { zh: "景秘不發喪，遷殯於昭陽殿，迎太子於永福省，使如常入朝。", literal: "Jing secretly withheld announcement of the death, moved the coffin to Zhaoyang Hall, summoned the crown prince from Yongfu Palace, and had him enter court as usual.", idiomatic: "Hou Jing secretly withheld announcement of the death, moved the coffin to Zhaoyang Hall, summoned the crown prince from Yongfu Palace, and had him enter court as usual." },
  { zh: "王偉、陳慶皆侍太子，太子嗚咽流涕，不敢洩聲，殿外文武皆莫之知。", literal: "Wang Wei and Chen Qing both attended the crown prince; the prince sobbed with tears but dared not make a sound; civil and military officials outside the hall none knew.", idiomatic: "Wang Wei and Chen Qing both attended the crown prince; the prince sobbed with tears but dared not make a sound; civil and military officials outside the hall knew nothing." },
  { zh: "東魏高岳既失慕容紹宗等，志氣沮喪，不敢復逼長社城。", literal: "Gao Yue of Eastern Wei, having lost Murong Shaozong and the others, was dispirited and dared not press Changshe again.", idiomatic: "Gao Yue of Eastern Wei, having lost Murong Shaozong and the others, was dispirited and dared not press Changshe again." },
  { zh: "陳元康言於大將軍澄曰：「王自輔政以來，未有殊功。", literal: "Chen Yuankang said to Grand General Cheng, \"Your Highness, since assisting in government, has had no extraordinary achievement.", idiomatic: "Chen Yuankang said to Grand General Cheng, \"Your Highness, since assisting in government, has had no extraordinary achievement." },
  { zh: "雖破侯景，本非外賊。", literal: "Though Hou Jing was defeated, he was never a foreign enemy.", idiomatic: "Though Hou Jing was defeated, he was never a foreign enemy." },
  { zh: "今穎川垂陷，願王自以為功。", literal: "Now Yingchuan is near falling; I wish Your Highness would make it your own achievement.", idiomatic: "Now Yingchuan is near falling; I wish Your Highness would make it your own achievement." },
  { zh: "」澄從之，戊寅，自將步騎十萬攻長社，親臨作堰。", literal: "\" Cheng agreed; on wuyin he personally led one hundred thousand infantry and cavalry to attack Changshe and personally oversaw building the dam.", idiomatic: "\" Cheng agreed; on wuyin he personally led one hundred thousand infantry and cavalry to attack Changshe and personally oversaw building the dam." },
  { zh: "堰三決，澄怒，推負土者及囊並塞之。", literal: "The dam broke three times; Cheng was angry and pushed those carrying earth and their bags together to fill the breach.", idiomatic: "The dam broke three times; Cheng was furious and drove earth-carriers and their bags together into the breach to fill it." },
  { zh: "辛巳，發高祖喪，升梓宮於太極殿。", literal: "On xinsi, the Gaozu's funeral was announced and the coffin was raised to the Hall of Supreme Ultimate.", idiomatic: "On xinsi, Emperor Wu's funeral was announced and the coffin was raised to the Hall of Supreme Ultimate." },
  { zh: "是日，太子即皇帝位，大赦。", literal: "That day the crown prince ascended the throne and proclaimed a general amnesty.", idiomatic: "That day the crown prince ascended the throne and proclaimed a general amnesty." },
  { zh: "侯景出屯朝堂，分兵守衛。", literal: "Hou Jing went out to camp at the Audience Hall and divided troops to guard.", idiomatic: "Hou Jing went out to camp at the Audience Hall and posted guards throughout the palace." },
  { zh: "壬午，詔北人在南為奴婢者，皆免之，所免萬計；", literal: "On renwu, an edict freed all northerners held as slaves and maidservants in the south; those freed numbered in the tens of thousands.", idiomatic: "On renwu, an edict freed all northerners held as slaves and maidservants in the south; those freed numbered in the tens of thousands." },
  { zh: "景或更加超擢，冀收其力。", literal: "Jing sometimes further promoted them abruptly, hoping to win their strength.", idiomatic: "Hou Jing sometimes promoted them further still, hoping to win their loyalty." },
  { zh: "高祖之末，建康士民服食、器用，爭尚豪華，糧無半年之儲，常資四方委輸。", literal: "At the end of Gaozu's reign, Jiankang gentry and commoners in dress, food, and utensils all vied in luxury; grain stores did not last half a year and always relied on deliveries from the four quarters.", idiomatic: "At the end of Emperor Wu's reign, Jiankang gentry and commoners vied in luxury of dress, food, and furnishings; grain stores did not last half a year and always relied on deliveries from the four quarters." },
  { zh: "自景作亂，道路斷絕，數月之間，人至相食，猶不免餓死，存者百無一二。", literal: "Since Jing's rebellion, roads were cut; within months men came to eating one another, yet still could not escape starvation; of those who survived, not one or two in a hundred remained.", idiomatic: "Since Hou Jing's rebellion, roads were cut; within months men came to eating one another, yet still could not escape starvation; scarcely one survivor in a hundred remained." },
  { zh: "貴戚、豪族皆自出采穭，填委溝壑，不可勝紀。", literal: "Nobles and powerful clans all went out themselves to gather wild grains; bodies filled gullies and ravines beyond counting.", idiomatic: "Nobles and powerful clans all went out themselves to gather wild grains; corpses filled gullies and ravines beyond counting." },
  { zh: "癸未，景遣儀同三司來亮入宛陵，宣城太守楊白華誘而斬之。", literal: "On guimwei, Jing sent Lai Liang, Equal in Honor to the Three Dukes, into Wanling; Xuancheng Administrator Yang Baihua lured and beheaded him.", idiomatic: "On guimwei, Hou Jing sent Lai Liang, Equal in Honor to the Three Dukes, into Wanling; Xuancheng Administrator Yang Baihua lured and beheaded him." },
  { zh: "甲申，景遣其將李賢明攻之，不克。", literal: "On jiashen, Jing sent his general Li Xianming to attack but could not take it.", idiomatic: "On jiashen, Hou Jing sent his general Li Xianming to attack but could not take it." },
  { zh: "景又遣中軍侯子鑒入吳郡，以廂公蘇單于為吳郡太守，遣儀同宋子仙等將兵東屯錢塘，新城戍主戴僧逖據縣拒之。", literal: "Jing again sent Central Army Commander Hou Zijian into Wu commandery, made Su Chanyu of the Secretariat Wu Administrator, and sent Song Zixian, Equal in Honor, and others east to camp at Qiantang; garrison commander Dai Sengti of Xincheng held the county and resisted.", idiomatic: "Hou Jing again sent Central Army Commander Hou Zijian into Wu commandery, made Su Chanyu of the Secretariat Wu Administrator, and sent Song Zixian and others east to camp at Qiantang; garrison commander Dai Sengti of Xincheng held the county and resisted." },
  { zh: "御史中丞沈浚避難東歸，至吳興，太守張嵊與之合謀，舉兵討景。", literal: "Censor-in-Chief Shen Jun fled eastward; reaching Wuxing, Administrator Zhang Sheng joined him in conspiracy and raised troops against Jing.", idiomatic: "Censor-in-Chief Shen Jun fled eastward; reaching Wuxing, Administrator Zhang Sheng joined him in conspiracy and raised troops against Hou Jing." },
  { zh: "嵊，稷之子也。", literal: "Sheng was Ji's son.", idiomatic: "Sheng was Ji's son." },
  { zh: "東揚州刺史臨城公大連，亦據州不受景命。", literal: "Eastern Yangzhou Inspector Duke Dalian of Lincheng also held the province and refused Jing's orders.", idiomatic: "Eastern Yangzhou Inspector Duke Dalian of Lincheng also held the province and refused Hou Jing's orders." },
  { zh: "景號令所行，唯吳郡以西、南陵以北而已。", literal: "Jing's orders took effect only west of Wu commandery and north of Nanling.", idiomatic: "Hou Jing's orders took effect only west of Wu commandery and north of Nanling." },
  { zh: "魏詔：「太和中代人改姓者皆復其舊。", literal: "A Wei edict: \"Those who changed surnames in the Taihe era shall all restore their old ones.", idiomatic: "A Western Wei edict: \"Those who changed surnames in the Taihe era shall all restore their old ones." },
  { zh: "六月，丙戌，以南康王會理為侍中、司空。", literal: "In the sixth month, on bingxu, Prince Huili of Nankang was made Palace Attendant and Minister of Works.", idiomatic: "In the sixth month, on bingxu, Prince Huili of Nankang was made Palace Attendant and Minister of Works." },
  { zh: "丁亥，立宣城王大器為皇太子。", literal: "On dinghai, Prince Daqi of Xuancheng was established as crown prince.", idiomatic: "On dinghai, Prince Daqi of Xuancheng was established as crown prince." },
  { zh: "初，侯景將使太常卿南陽劉之遴授臨賀王正德璽綬，之遴剃髮僧服而逃。", literal: "Earlier, Hou Jing was about to have Minister of Ceremonies Liu Zhilin of Nanyang invest Prince Zhengde of Linhe with seal and sash; Zhilin shaved his head, put on monk's robes, and fled.", idiomatic: "Earlier, Hou Jing was about to have Minister of Ceremonies Liu Zhilin of Nanyang invest Prince Zhengde of Linhe with seal and sash; Zhilin shaved his head, put on monk's robes, and fled." },
  { zh: "之遴博學能文，嘗為湘東王繹長史；", literal: "Zhilin was learned and literate and had once been chief administrator to Prince Yi of Xiangdong.", idiomatic: "Zhilin was learned and literate and had once been chief administrator to Prince Yi of Xiangdong." },
  { zh: "將歸江陵，繹素嫉其才，己丑，之遴至夏口，繹密送藥殺之，而自為志銘，厚其賻贈。", literal: "As he was returning to Jiangling, Yi had long envied his talent; on jichou, when Zhilin reached Xiakou, Yi secretly sent poison and killed him, then wrote his epitaph himself and gave generous funeral gifts.", idiomatic: "As he was returning to Jiangling, Yi had long envied his talent; on jichou, when Zhilin reached Xiakou, Yi secretly sent poison and killed him, then wrote his epitaph himself and gave generous funeral gifts." },
  { zh: "壬辰，封皇子大心為尋陽王，大款為江陵王，大臨為南海王，大連為南郡王，大春為安陸王，大成為山陽王，大封為宜都王。", literal: "On renchen, the princes were enfeoffed: Daxin as Prince of Xunyang, Dakuan as Prince of Jiangling, Dalin as Prince of Nanhai, Dalian as Prince of Nan commandery, Dachun as Prince of Anlu, dacheng as Prince of Shanyang, and Dafeng as Prince of Yidu.", idiomatic: "On renchen, the princes were enfeoffed: Daxin as Prince of Xunyang, Dakuan as Prince of Jiangling, Dalin as Prince of Nanhai, Dalian as Prince of Nan commandery, Dachun as Prince of Anlu, Dacheng as Prince of Shanyang, and Dafeng as Prince of Yidu." },
  { zh: "長社城中無鹽，人病攣腫，死者什八九。", literal: "Within Changshe there was no salt; people sickened with cramps and swelling; eight or nine in ten died.", idiomatic: "Within Changshe there was no salt; people sickened with cramps and swelling; eight or nine in ten died." },
  { zh: "大風從西北起，吹水入城，城壞。", literal: "A great wind rose from the northwest, blew water into the city, and the walls broke.", idiomatic: "A great wind rose from the northwest, blew floodwater into the city, and the walls gave way." },
  { zh: "東魏大將軍澄令城中曰：「有能生致王大將軍者封侯；", literal: "Grand General Cheng of Eastern Wei proclaimed to the city, \"Whoever can deliver General Wang alive shall be enfeoffed as a marquis;", idiomatic: "Grand General Gao Cheng of Eastern Wei proclaimed to the city, \"Whoever can deliver General Wang alive shall be enfeoffed as a marquis;" },
  { zh: "若大將軍身有損傷，親近左右皆斬。", literal: "if General Wang's person suffers harm, all those close at hand shall be beheaded.", idiomatic: "if General Wang's person suffers harm, all those close at hand shall be beheaded." },
  { zh: "」王思政帥眾據土山，告之曰：「吾力屈計窮，唯當以死謝國！", literal: "\" Wang Sizheng led his men to hold an earthen hill and told them, \"My strength is spent and my plans exhausted—I can only repay the state with death!", idiomatic: "\" Wang Sizheng led his men to hold an earthen hill and told them, \"My strength is spent and my plans exhausted—I can only repay the state with death!" },
  { zh: "」因仰天大哭，西向再拜，欲自刎，都督駱訓曰：「公常語訓等：『汝繼我頭出降，非但得富貴，亦完一城人。", literal: "\" He then looked skyward and wailed, bowed twice toward the west, and meant to cut his own throat; commander Luo Xun said, \"My lord often told Xun and the rest, 'You take my head and surrender—not only will you gain wealth and honor, you will also save a whole city of people.", idiomatic: "\" He then looked skyward and wailed, bowed twice toward the west, and meant to cut his own throat; commander Luo Xun said, \"My lord often told us, 'You take my head and surrender—not only will you gain wealth and honor, you will also save a whole city of people." },
  { zh: "』今高相既有此令，公獨不哀士卒之死乎！", literal: "' Now Chancellor Gao has issued this order—does my lord alone not pity the soldiers' deaths!", idiomatic: "' Now Chancellor Gao has issued this order—does my lord alone not pity the soldiers' deaths!" },
  { zh: "」眾共執之，不得引決。", literal: "\" The crowd together seized him and he could not carry out his resolve.", idiomatic: "\" The crowd together seized him and he could not carry out his resolve." },
  { zh: "澄遣通直散騎趙彥深就土山遺以白羽扇，執手申意，牽之以下。", literal: "Cheng sent Direct Attendant Zhao Yanshen to the earthen hill with a white-feather fan as gift, took his hand to convey goodwill, and drew him down.", idiomatic: "Cheng sent Direct Attendant Zhao Yanshen to the earthen hill with a white-feather fan as gift, took his hand to convey goodwill, and drew him down." },
  { zh: "澄不令拜，延而禮之。", literal: "Cheng did not require him to bow but received and honored him.", idiomatic: "Cheng did not require him to bow but received and honored him." },
  { zh: "思政初入穎川，將士八千人，及城陷，才三千人，卒無叛者。", literal: "When Sizheng first entered Yingchuan he had eight thousand officers and soldiers; when the city fell there were only three thousand, yet in the end none rebelled.", idiomatic: "When Sizheng first entered Yingchuan he had eight thousand officers and soldiers; when the city fell there were only three thousand, yet in the end none rebelled." },
  { zh: "澄悉散配其將卒於遠方，改穎川為鄭州，禮遇思政甚重。", literal: "Cheng dispersed and assigned all his officers and soldiers to distant places, renamed Yingchuan Zheng province, and treated Sizheng with great honor.", idiomatic: "Cheng dispersed and assigned all his officers and soldiers to distant places, renamed Yingchuan Zheng province, and treated Sizheng with great honor." },
  { zh: "西閣祭酒盧潛曰：「思政不能死節，何足可重！", literal: "Western Pavilion Libationer Lu Qian said, \"Sizheng could not die maintaining integrity—what is there to honor!", idiomatic: "Western Pavilion Libationer Lu Qian said, \"Sizheng could not die maintaining integrity—what is there to honor!" },
  { zh: "」澄謂左右曰：「我有盧潛，乃是更得一王思政。", literal: "\" Cheng told those around him, \"With Lu Qian, I have gained another Wang Sizheng.", idiomatic: "\" Cheng told those around him, \"With Lu Qian, I have gained another Wang Sizheng." },
  { zh: "」潛，度世之曾孫也。", literal: "\" Qian was the great-grandson of Dushi.", idiomatic: "\" Qian was the great-grandson of Dushi." },
  { zh: "初，思政屯襄城，欲以長社為行台治所，遣使者魏仲啟陳於太師泰，並致書於淅州刺史崔猷。", literal: "Earlier, Sizheng had garrisoned Xiangcheng and wished to make Changshe the seat of the Mobile Headquarters; he sent envoy Wei Zhong to report to Grand Preceptor Tai and also wrote to Xi province Inspector Cui You.", idiomatic: "Earlier, Sizheng had garrisoned Xiangcheng and wished to make Changshe the seat of the Mobile Headquarters; he sent envoy Wei Zhong to report to Grand Preceptor Yuwen Tai and also wrote to Xi province Inspector Cui You." },
  { zh: "猷復書曰：「襄城控帶京、洛，實當今之要地，如有動靜，易相應接。", literal: "You replied, \"Xiangcheng commands the approaches to Luoyang and is truly a vital place today; if there is any movement, response is easy.", idiomatic: "You replied, \"Xiangcheng commands the approaches to Luoyang and is truly a vital place today; if there is any movement, response is easy." },
  { zh: "穎川既鄰寇境，又無山川之固，賊若潛來，逕至城下。", literal: "Yingchuan borders enemy territory and lacks natural defenses; if the enemy comes secretly, he reaches the walls directly.", idiomatic: "Yingchuan borders enemy territory and lacks natural defenses; if the enemy comes secretly, he reaches the walls directly." },
  { zh: "莫若頓兵襄城。", literal: "Better halt the army at Xiangcheng.", idiomatic: "Better halt the army at Xiangcheng." },
  { zh: "為行台之所。", literal: "Make it the seat of the Mobile Headquarters.", idiomatic: "Make it the seat of the Mobile Headquarters." },
  { zh: "穎川置州，遣良將鎮守，則表裡膠固，人心易安，縱有不虞，豈能為患！", literal: "Establish a province at Yingchuan and send a good general to garrison it—then inner and outer will be firmly joined, hearts will be easy to settle, and even if something unexpected occurs, how could it become a threat!", idiomatic: "Establish a province at Yingchuan and send a good general to garrison it—then inner and outer will be firmly joined, hearts will be easy to settle, and even if something unexpected occurs, how could it become a threat!" },
  { zh: "」仲見泰，具以啟聞。", literal: "\" Zhong saw Tai and reported everything in full.", idiomatic: "\" Zhong saw Tai and reported everything in full." },
  { zh: "泰令依猷策。", literal: "Tai ordered that You's plan be followed.", idiomatic: "Tai ordered that You's plan be followed." },
  { zh: "思政固請，且約：「賊水攻期年、陸攻三年之內，朝廷不煩赴救。", literal: "Sizheng firmly petitioned and moreover pledged, \"Within one year of water attack or three years of land attack, the court need not trouble itself to send rescue.", idiomatic: "Sizheng firmly petitioned and moreover pledged, \"Within one year of water attack or three years of land attack, the court need not trouble itself to send rescue." },
  { zh: "」泰乃許之。", literal: "\" Tai then consented.", idiomatic: "\" Tai then consented." },
  { zh: "及長社不守，泰深悔之。", literal: "When Changshe could not be held, Tai deeply regretted it.", idiomatic: "When Changshe fell, Tai deeply regretted it." },
  { zh: "猷，孝芬之子也。", literal: "You was Xiaofen's son.", idiomatic: "You was Xiaofen's son." },
  { zh: "侯景之南叛也，丞相泰恐東魏復取景所部地，使諸將分守諸城。", literal: "When Hou Jing rebelled southward, Chancellor Tai feared Eastern Wei would again take the territories Jing had held and had generals divide forces to guard the cities.", idiomatic: "When Hou Jing rebelled southward, Chancellor Yuwen Tai feared Eastern Wei would again take the territories Hou Jing had held and had generals divide forces to guard the cities." },
  { zh: "及穎川陷，泰以諸城道路阻絕，皆令拔軍還。", literal: "When Yingchuan fell, Tai, seeing roads to the various cities cut off, ordered all armies withdrawn.", idiomatic: "When Yingchuan fell, Tai, seeing roads to the various cities cut off, ordered all armies withdrawn." },
  { zh: "上甲侯韶自建康出奔江陵，稱受高祖密詔徵兵，以湘東王繹為侍中、假黃鉞、大都督中外諸軍事、司徒、承製，自餘籓鎮並加位號。", literal: "Hou Shao of Shangjia fled Jiankang for Jiangling, claiming he bore Gaozu's secret orders to raise troops; Prince Yi of Xiangdong was made Palace Attendant, granted the yellow battle-axe, Grand Commander of All Forces Inside and Outside, Minister of Education, and regent; the remaining princes and garrisons all received added titles.", idiomatic: "Hou Shao of Shangjia fled Jiankang for Jiangling, claiming he bore Emperor Wu's secret orders to raise troops; Prince Yi of Xiangdong was made Palace Attendant, granted the yellow battle-axe, Grand Commander of All Forces Inside and Outside, Minister of Education, and regent; the remaining princes and garrisons all received added titles." },
  { zh: "宋子仙圍戴僧逖，不克。", literal: "Song Zixian besieged Dai Sengti but could not take him.", idiomatic: "Song Zixian besieged Dai Sengti but could not take him." },
  { zh: "丙午，吳盜陸緝等起兵襲吳郡，殺蘇單于，推前淮南太守文成侯寧為主。", literal: "On bingwu, bandits of Wu led by Lu Ji and others rose, struck Wu commandery, killed Su Chanyu, and set up former Huainan Administrator Marquis Ning of Wencheng as leader.", idiomatic: "On bingwu, bandits of Wu led by Lu Ji and others rose, struck Wu commandery, killed Su Chanyu, and set up former Huainan Administrator Marquis Ning of Wencheng as leader." },
  { zh: "臨賀王正德怨侯景賣己，密書召鄱陽王范，使以兵入；", literal: "Prince Zhengde of Linhe resented Hou Jing for betraying him and secretly wrote summoning Prince Fan of Poyang to enter with troops.", idiomatic: "Prince Zhengde of Linhe resented Hou Jing for betraying him and secretly wrote summoning Prince Fan of Poyang to enter with troops." },
  { zh: "景遮得其書，癸丑，縊殺正德。", literal: "Jing intercepted the letter; on guichou he strangled Zhengde.", idiomatic: "Hou Jing intercepted the letter; on guichou he strangled Zhengde." },
  { zh: "景以儀同三司郭元建為尚書僕射、北道行台、總江北諸軍事，鎮新秦；", literal: "Jing made Guo Yuanjian, Equal in Honor to the Three Dukes, Vice Director of the Masters of Writing, Northern Route Mobile Headquarters, overall commander of all military affairs north of the river, garrisoning Xinqin.", idiomatic: "Hou Jing made Guo Yuanjian, Equal in Honor to the Three Dukes, Vice Director of the Masters of Writing, Northern Route Mobile Headquarters, overall commander of all military affairs north of the river, garrisoning Xinqin." },
  { zh: "封元羅等諸元十餘人皆為王。", literal: "More than ten members of the Yuan clan including Yuan Luo were all enfeoffed as princes.", idiomatic: "More than ten members of the Yuan clan including Yuan Luo were all enfeoffed as princes." },
  { zh: "景愛永安侯確之勇，常置左右。", literal: "Jing admired the courage of Marquis Que of Yong'an and kept him always at his side.", idiomatic: "Hou Jing admired the courage of Marquis Que of Yong'an and kept him always at his side." },
  { zh: "邵陵王綸潛遣人呼之，確曰：「景輕佻，一夫力耳，我欲手刃之，正恨未得其便，卿還啟家王，勿以確為念。", literal: "Prince Lun of Shaoling secretly sent someone to summon him; Que said, \"Jing is frivolous—a single man's strength; I wish to kill him with my own hand and only regret I have not yet found the chance; return and report to my house's prince, and do not worry about Que.", idiomatic: "Prince Lun of Shaoling secretly sent someone to summon him; Que said, \"Hou Jing is frivolous—a single man's strength; I wish to kill him with my own hand and only regret I have not yet found the chance; return and report to my prince, and do not worry about me." },
  { zh: "」景與確游鐘山，引弓射鳥，因欲射景，弦斷，不發，景覺而殺之。", literal: "\" Jing went with Que to roam Zhong Mountain, drew bow to shoot birds, then meant to shoot Jing; the string snapped and would not release; Jing noticed and killed him.", idiomatic: "\" Hou Jing went with Que to roam Zhong Mountain, drew bow to shoot birds, then meant to shoot Hou Jing; the string snapped and would not release; Hou Jing noticed and killed him." },
  { zh: "湘東王繹娶徐孝嗣孫女為妃，生世子方等。", literal: "Prince Yi of Xiangdong married a granddaughter of Xu Xiaosi as consort and begot the heir Fangdeng.", idiomatic: "Prince Yi of Xiangdong married a granddaughter of Xu Xiaosi as consort and begot the heir Fangdeng." },
  { zh: "妃丑而妒，又多失行，繹二三年一至其室。", literal: "The consort was ugly and jealous and had many moral failings; Yi visited her chamber once every two or three years.", idiomatic: "The consort was ugly and jealous and had many moral failings; Yi visited her chamber once every two or three years." },
  { zh: "妃聞繹當至，以繹目眇，為半面妝以待之，繹怒而出，故方等亦無寵。", literal: "When the consort heard Yi was coming, knowing Yi was blind in one eye, she made up only half her face to receive him; Yi left in anger, and so Fangdeng also had no favor.", idiomatic: "When the consort heard Yi was coming, knowing Yi was blind in one eye, she made up only half her face to receive him; Yi left in anger, and so Fangdeng also had no favor." },
  { zh: "及自建康還江陵，繹見其御軍和整，始歎其能，入告徐妃，妃不對，垂泣而退。", literal: "When he returned from Jiankang to Jiangling, Yi saw Fangdeng's command of troops was orderly and disciplined and began to admire his ability; he went in and told Consort Xu; she did not answer but withdrew weeping.", idiomatic: "When he returned from Jiankang to Jiangling, Yi saw Fangdeng's command of troops was orderly and disciplined and began to admire his ability; he went in and told Consort Xu; she did not answer but withdrew weeping." },
  { zh: "繹怒，疏其穢行，榜於大閤，方等見之，益懼。", literal: "Yi was angered, listed her disgraceful conduct, and posted it on the great gate; Fangdeng saw it and grew still more afraid.", idiomatic: "Yi was angered, listed her disgraceful conduct, and posted it on the great gate; Fangdeng saw it and grew still more afraid." },
  { zh: "湘州刺史河東王譽，驍勇得士心，繹將討侯景，遣使督其糧眾，譽曰：「各自軍府，何忽隸人！", literal: "Xiangzhou Inspector Prince Yu of Hedong was fierce and brave and won soldiers' hearts; as Yi was about to campaign against Hou Jing he sent an envoy to command his grain and troops; Yu said, \"Each has his own headquarters—why suddenly become someone else's subordinate!", idiomatic: "Xiangzhou Inspector Prince Yu of Hedong was fierce and brave and won soldiers' hearts; as Yi was about to campaign against Hou Jing he sent an envoy to command his grain and troops; Yu said, \"Each has his own headquarters—why suddenly become someone else's subordinate!" },
  { zh: "」使者三返，譽不與。", literal: "\" The envoy returned three times; Yu would not comply.", idiomatic: "\" The envoy returned three times; Yu would not comply." },
  { zh: "方等請討之，繹乃以少子安南侯方矩為湘州刺史，使方等將精卒二萬送之。", literal: "Fangdeng asked to campaign against him; Yi then made his youngest son Marquis Fangju of Annan Inspector of Xiangzhou and sent Fangdeng with twenty thousand elite troops to escort him.", idiomatic: "Fangdeng asked to campaign against him; Yi then made his youngest son Marquis Fangju of Annan Inspector of Xiangzhou and sent Fangdeng with twenty thousand elite troops to escort him." },
  { zh: "方等將行，謂所親曰：「是行也，吾必死之；", literal: "As Fangdeng was about to depart, he told those close to him, \"On this journey I am sure to die;", idiomatic: "As Fangdeng was about to depart, he told those close to him, \"On this journey I am sure to die;" },
  { zh: "死得其所，吾復奚恨！", literal: "dying in the right place—what more would I regret!", idiomatic: "dying in the right place—what more would I regret!" },
  { zh: "侯景以趙威方為豫章太守，江州刺史尋陽王大心遣軍拒之，擒威方，系州獄，威方逃還建康。", literal: "Hou Jing made Zhao Weifang Administrator of Yuzhang; Jiangzhou Inspector Prince Daxin of Xunyang sent troops to resist, captured Weifang, and imprisoned him in the provincial jail; Weifang escaped back to Jiankang.", idiomatic: "Hou Jing made Zhao Weifang Administrator of Yuzhang; Jiangzhou Inspector Prince Daxin of Xunyang sent troops to resist, captured Weifang, and imprisoned him in the provincial jail; Weifang escaped back to Jiankang." },
  { zh: "湘東世子方等軍至麻溪，河東王譽將七千人擊之，方等軍敗，溺死。", literal: "The Xiangdong heir Fangdeng's army reached Maxi; Prince Yu of Hedong with seven thousand men struck; Fangdeng's army was defeated and he drowned.", idiomatic: "The Xiangdong heir Fangdeng's army reached Maxi; Prince Yu of Hedong with seven thousand men struck; Fangdeng's army was defeated and he drowned." },
  { zh: "安南侯方矩收餘眾還江陵，湘東王繹無戚容。", literal: "Marquis Fangju of Annan gathered the survivors and returned to Jiangling; Prince Yi of Xiangdong showed no grief.", idiomatic: "Marquis Fangju of Annan gathered the survivors and returned to Jiangling; Prince Yi of Xiangdong showed no grief." },
  { zh: "繹寵姬王氏，生子方諸。", literal: "Yi favored concubine Lady Wang, who bore Fangzhu.", idiomatic: "Yi favored concubine Lady Wang, who bore Fangzhu." },
  { zh: "王氏卒，繹疑徐妃為之，逼令自殺，妃赴井死，葬以庶人禮，不聽諸子制服。", literal: "When Wang died, Yi suspected Consort Xu had done it, forced her to kill herself; the consort threw herself into a well and died; she was buried with commoner rites and her sons were forbidden mourning dress.", idiomatic: "When Wang died, Yi suspected Consort Xu had done it and forced her to kill herself; the consort threw herself into a well and died; she was buried with commoner rites and her sons were forbidden mourning dress." },
  { zh: "西江督護陳霸先欲起兵討侯景，景使人誘廣州刺史元景仲，許奉以為主，景仲由是附景，陰圖霸先。", literal: "West River Protector Chen Baxian wished to raise troops against Hou Jing; Jing sent men to entice Guangzhou Inspector Yuan Jingzhong, promising to make him ruler; Jingzhong therefore joined Jing and secretly plotted against Baxian.", idiomatic: "West River Protector Chen Baxian wished to raise troops against Hou Jing; Hou Jing sent men to entice Guangzhou Inspector Yuan Jingzhong, promising to make him ruler; Jingzhong therefore joined Hou Jing and secretly plotted against Baxian." },
  { zh: "霸先知之，與成州刺史王懷明等集兵南海，馳檄以討景仲曰：「元景仲與賊合從，朝廷遣曲陽侯勃為刺史，軍已頓朝亭。", literal: "Baxian learned of it; with Chengzhou Inspector Wang Huaiming and others he gathered troops at Nanhai and issued a rapid proclamation against Jingzhong, saying, \"Yuan Jingzhong has joined the rebels; the court has sent Marquis Bo of Quyang as inspector and the army has already encamped at Chaoting.", idiomatic: "Baxian learned of it; with Chengzhou Inspector Wang Huaiming and others he gathered troops at Nanhai and issued a rapid proclamation against Jingzhong: \"Yuan Jingzhong has joined the rebels; the court has sent Marquis Bo of Quyang as inspector and the army has already encamped at Chaoting." },
  { zh: "」景仲所部聞之，皆棄景仲而散。", literal: "\" Jingzhong's followers, hearing this, all abandoned him and dispersed.", idiomatic: "\" Jingzhong's followers, hearing this, all abandoned him and dispersed." },
  { zh: "秋，七月，甲寅，景仲縊於閣下。", literal: "In autumn, the seventh month, on jiayin, Jingzhong hanged himself beneath the pavilion.", idiomatic: "In autumn, the seventh month, on jiayin, Jingzhong hanged himself beneath the pavilion." },
  { zh: "霸先迎定州刺史蕭勃鎮廣州。", literal: "Baxian welcomed Dingzhou Inspector Xiao Bo to garrison Guangzhou.", idiomatic: "Baxian welcomed Dingzhou Inspector Xiao Bo to garrison Guangzhou." },
  { zh: "前高州刺史蘭裕，欽之弟也，與其諸弟扇誘始興等十郡，攻監衡州事歐陽頠。", literal: "Former Gaozhou Inspector Lan Yu, Qin's younger brother, with his brothers incited Shixing and nine other commanderies and attacked Ouyang Yu, who supervised Hengzhou affairs.", idiomatic: "Former Gaozhou Inspector Lan Yu, Qin's younger brother, with his brothers incited Shixing and nine other commanderies and attacked Ouyang Yu, who supervised Hengzhou affairs." },
  { zh: "勃使霸先救之，悉擒裕等，勃因以霸先監始興郡事。", literal: "Bo sent Baxian to the rescue; Yu and the others were all captured; Bo therefore made Baxian supervisor of Shixing commandery affairs.", idiomatic: "Bo sent Baxian to the rescue; Yu and the others were all captured; Bo therefore made Baxian supervisor of Shixing commandery affairs." },
  { zh: "湘東王繹遣竟陵太守王僧辯、信州刺史東海鮑泉擊湘州，分給兵糧，刻日就道。", literal: "Prince Yi of Xiangdong sent Jingling Administrator Wang Senbian and Xin province Inspector Bao Quan of Donghai to attack Xiangzhou, allotting troops and grain with a fixed day for departure.", idiomatic: "Prince Yi of Xiangdong sent Jingling Administrator Wang Senbian and Xin province Inspector Bao Quan of Donghai to attack Xiangzhou, allotting troops and grain with a fixed day for departure." },
  { zh: "僧辯以竟陵部下未盡至，欲俟眾集然後行，與泉入白繹，求申期日。", literal: "Senbian, because his Jingling troops had not all arrived, wished to wait until the force was assembled before marching; he and Quan entered to report to Yi and asked to extend the deadline.", idiomatic: "Senbian, because his Jingling troops had not all arrived, wished to wait until the force was assembled before marching; he and Quan entered to report to Yi and asked to extend the deadline." },
  { zh: "繹疑僧辯觀望，按劍厲聲曰：「卿憚行拒命，欲同賊邪？", literal: "Yi suspected Senbian was hesitating; he grasped his sword and said in a harsh voice, \"You fear marching and refuse orders—do you wish to join the rebels?", idiomatic: "Yi suspected Senbian was hesitating; he grasped his sword and said in a harsh voice, \"You fear marching and refuse orders—do you wish to join the rebels?" },
  { zh: "今日唯有死耳！", literal: "Today there is only death!", idiomatic: "Today there is only death!" },
  { zh: "」因斫僧辯，中其左髀，悶絕，久之方蘇，即送獄。", literal: "\" He then struck at Senbian, hitting his left thigh; Senbian fainted and only after long time revived; he was sent at once to prison.", idiomatic: "\" He then struck at Senbian, hitting his left thigh; Senbian fainted and only after a long time revived; he was sent at once to prison." },
  { zh: "泉震怖，不敢言。", literal: "Quan was shaken with terror and dared not speak.", idiomatic: "Quan was shaken with terror and dared not speak." },
  { zh: "僧辯母徒行流涕入謝，自陳無訓，繹意解，賜以良藥，故得不死。", literal: "Senbian's mother walked in on foot weeping to apologize, confessing she had failed in training; Yi's anger eased; he granted good medicine, and so Senbian did not die.", idiomatic: "Senbian's mother walked in on foot weeping to apologize, confessing she had failed in training; Yi's anger eased; he granted good medicine, and so Senbian did not die." },
  { zh: "丁卯，鮑泉獨將兵伐湘州。", literal: "On dingmao, Bao Quan alone led troops to campaign against Xiangzhou.", idiomatic: "On dingmao, Bao Quan alone led troops to campaign against Xiangzhou." },
  { zh: "陸輯等競為暴掠，吳人不附，宋子仙自錢塘旋軍擊之。", literal: "Lu Ji and the others competed in violent plunder; the people of Wu would not follow them; Song Zixian turned his army from Qiantang to strike them.", idiomatic: "Lu Ji and the others competed in violent plunder; the people of Wu would not follow them; Song Zixian turned his army from Qiantang to strike them." },
  { zh: "壬戌，緝棄城奔海鹽，子仙復據吳郡。", literal: "On renxu, Ji abandoned the city and fled to Haiyan; Zixian again held Wu commandery.", idiomatic: "On renxu, Ji abandoned the city and fled to Haiyan; Zixian again held Wu commandery." },
  { zh: "戊辰，侯景置吳州於吳郡，以安陸王大春為刺史。", literal: "On wuchen, Hou Jing established Wu province in Wu commandery and made Prince Dachun of Anlu its inspector.", idiomatic: "On wuchen, Hou Jing established Wu province in Wu commandery and made Prince Dachun of Anlu its inspector." },
  { zh: "庚午，以南康王會理兼尚書令。", literal: "On gengwu, Prince Huili of Nankang was additionally made Director of the Masters of Writing.", idiomatic: "On gengwu, Prince Huili of Nankang was additionally made Director of the Masters of Writing." },
  { zh: "鄱陽王范聞建康不守，戒嚴，欲入，僚佐或說之曰：「今魏人已據壽陽，大王移足，則虜騎必窺合肥。", literal: "Prince Fan of Poyang, hearing Jiankang had not held, ordered martial law and intended to enter; some staff urged him, saying, \"The Wei men now hold Shouyang; if Your Highness moves a step, enemy cavalry will surely watch Hefei.", idiomatic: "Prince Fan of Poyang, hearing Jiankang had fallen, ordered martial law and intended to march in; some staff urged him: \"The Wei men now hold Shouyang; if Your Highness moves a step, enemy cavalry will surely watch Hefei." },
  { zh: "前賊未平，後城失守，將若之何！", literal: "The rebels in front are not yet pacified; the city behind may be lost—what then!", idiomatic: "The rebels in front are not yet pacified; the city behind may be lost—what then!" },
  { zh: "不如待四方兵集，使良將將精卒赴之，進不失勤王，退可固本根。", literal: "Better wait until troops from the four quarters assemble, send a good general with elite soldiers to the rescue—advancing you will not fail in saving the throne, retreating you can secure your base.", idiomatic: "Better wait until troops from the four quarters assemble, send a good general with elite soldiers to the rescue—advancing you will not fail in saving the throne, retreating you can secure your base." },
  { zh: "」范乃止。", literal: "\" Fan then stopped.", idiomatic: "\" Fan then abandoned the plan." },
  { zh: "會東魏大將軍澄遣西兗州刺史李伯穆逼合肥，又使魏收為書諭范。", literal: "Just then Eastern Wei Grand General Cheng sent Western Yanzhou Inspector Li Bomu to press Hefei, and also had Wei Shou write a letter to instruct Fan.", idiomatic: "Just then Eastern Wei grand general Gao Cheng sent Western Yanzhou inspector Li Bomu to press Hefei, and also had Wei Shou write to counsel Fan." },
  { zh: "范方謀討侯景，藉東魏為援，乃帥戰士二萬出東關，以合州輸伯穆，並遣咨議劉靈議送二子勤、廣為質於東魏以乞師。", literal: "Fan was then plotting to attack Hou Jing and sought Eastern Wei as aid; he led twenty thousand warriors out through Dongguan, supplied Bomu from the whole province, and sent advisory staff officer Liu Lingyi to deliver his two sons Qin and Guang as hostages to Eastern Wei to beg for troops.", idiomatic: "Fan was plotting to attack Hou Jing and sought Eastern Wei as ally; he led twenty thousand warriors out through Dongguan, supplied Bomu from the whole province, and sent advisory staff officer Liu Lingyi to deliver his sons Qin and Guang as hostages to Eastern Wei to beg for troops." },
  { zh: "范屯濡須以待上游之軍，遣世子嗣將千餘人守安樂柵，上遊軍皆不下，范糧乏，采菰稗、菱藕以自給。", literal: "Fan encamped at Ruxu to await upstream armies, sent his heir Si with more than a thousand men to hold Anle stockade; upstream armies all did not come down; Fan's grain ran short, and he gathered wild rice, water chestnuts, and lotus roots to sustain himself.", idiomatic: "Fan encamped at Ruxu to await upstream armies and sent his heir Si with more than a thousand men to hold Anle stockade; upstream armies never came down. Fan's grain ran short, and he gathered wild rice, water chestnuts, and lotus roots to sustain himself." },
  { zh: "勤、廣至鄴，東魏人竟不為出師。", literal: "Qin and Guang reached Ye, but the Eastern Wei men would not send troops after all.", idiomatic: "Qin and Guang reached Ye, but the Eastern Wei court would not send troops after all." },
  { zh: "范進退無計，乃溯流西上，軍於樅陽。", literal: "Fan had no plan whether to advance or retreat; he then went upstream westward and encamped at Zongyang.", idiomatic: "Fan, caught with no way forward or back, went upstream westward and encamped at Zongyang." },
  { zh: "景出屯姑孰，范將裴之悌以眾降之。", literal: "Jing went out and encamped at Gudu; Fan's general Pei Zhiti surrendered with his troops.", idiomatic: "Jing marched out and encamped at Gudu; Fan's general Pei Zhiti surrendered with his troops." },
  { zh: "之悌，之高之弟也。", literal: "Zhiti was Zhigao's younger brother.", idiomatic: "Zhiti was the younger brother of Pei Zhigao." },
  { zh: "東魏大將軍澄詣鄴，辭爵位殊禮，且請立太子。", literal: "Eastern Wei Grand General Cheng went to Ye, declined special honors of rank, and also asked that a crown prince be installed.", idiomatic: "Eastern Wei grand general Gao Cheng went to Ye, declined special honors of rank, and also asked that a crown prince be installed." },
  { zh: "澄謂濟陰王暉業曰：「比讀何書？", literal: "Cheng said to Prince of Jiyin Huiye, \"What books have you been reading lately?", idiomatic: "Cheng said to Prince Huiye of Jiyin, \"What books have you been reading lately?" },
  { zh: "」暉業曰：「數尋伊、霍之傳，不讀曹、馬之書。", literal: "\" Huiye said, \"I often seek the records of Yi Yin and Huo Guang; I do not read the books of Cao and Sima.", idiomatic: "\" Huiye said, \"I often study the records of Yi Yin and Huo Guang; I do not read the books of Cao and Sima.\"" },
  { zh: "八月，甲申朔，侯景遣其中軍都督侯子鑒等擊吳興。", literal: "In the eighth month, on the first day jiashen, Hou Jing sent his Central Army Commander Hou Zijian and others to attack Wuxing.", idiomatic: "In the eighth month, on the first day jiashen, Hou Jing sent his central army commander Hou Zijian and others to attack Wuxing." },
  { zh: "己亥，鮑泉軍於石槨寺，河東王譽逆戰而敗；", literal: "On jihai, Bao Quan encamped at Shiguosi; Prince of Hedong Yu met him in battle and was defeated;", idiomatic: "On jihai, Bao Quan encamped at Shiguosi; Prince Xiao Yu of Hedong met him in battle and was defeated;" },
  { zh: "辛丑，又敗於橘洲，戰及溺死者萬餘人。", literal: "on xinchou, he was defeated again at Juzhou; those killed in battle and drowned numbered more than ten thousand.", idiomatic: "on xinchou he was defeated again at Juzhou; more than ten thousand were killed in battle or drowned." },
  { zh: "譽退保長沙，泉引軍圍之。", literal: "Yu withdrew to hold Changsha; Quan led his army to besiege it.", idiomatic: "Yu withdrew to hold Changsha; Quan led his army to besiege it." },
  { zh: "辛卯，東魏立皇子長仁為太子。", literal: "On xinmao, Eastern Wei installed the emperor's son Changren as crown prince.", idiomatic: "On xinmao, Eastern Wei installed the emperor's son Changren as crown prince." },
  { zh: "勃海文襄王高澄以其弟太原公洋次長，意常忌之。", literal: "Prince Wenxiang of Bohai, Gao Cheng, because his younger brother Prince of Taiyuan Yang was next in age, often harbored suspicion of him.", idiomatic: "Prince Wenxiang of Bohai, Gao Cheng, because his younger brother Prince Yang of Taiyuan was next in age, often harbored suspicion of him." },
  { zh: "洋深自晦匿，言不出口，常自貶退，與澄言，無不順從。", literal: "Yang deeply concealed himself, rarely speaking; he constantly belittled himself, and in speaking with Cheng never failed to obey.", idiomatic: "Yang kept himself deeply concealed, rarely speaking; he constantly belittled himself, and in speaking with Cheng never failed to obey." },
  { zh: "澄輕之，常曰：「此人亦得富貴，相書亦何可解！", literal: "Cheng looked down on him and often said, \"This man can also attain wealth and rank—what can physiognomy books explain!", idiomatic: "Cheng looked down on him and often said, \"This man can also attain wealth and rank—what can physiognomy books explain!" },
  { zh: "」洋為其夫人趙郡李氏營服玩小佳，澄輒奪取之；", literal: "\" Yang had made some fine clothes and ornaments for his wife, Lady Li of Zhao Commandery; Cheng would seize them;", idiomatic: "\" Yang had made some fine clothes and ornaments for his wife, Lady Li of Zhao Commandery; Cheng would seize them;" },
  { zh: "夫人或恚未與，洋笑曰：「此物猶應可求，兄須何容吝惜！", literal: "when his wife was angry and withheld them, Yang smiled and said, \"These things can still be sought again—why should elder brother be so stingy!", idiomatic: "when his wife was angry and withheld them, Yang smiled and said, \"These things can still be sought again—why should elder brother be so stingy!" },
  { zh: "」澄或愧不取，洋即受之，亦無飾讓。", literal: "\" Cheng sometimes, ashamed, did not take them; Yang then accepted them without pretense of refusal.", idiomatic: "\" Cheng sometimes, ashamed, did not take them; Yang then accepted them without pretense of refusal." },
  { zh: "每退朝還第，輒閉閣靜坐，雖對妻子，能竟日不言。", literal: "Whenever he returned from court to his residence, he would shut his doors and sit in silence; even before wife and children he could pass a whole day without speaking.", idiomatic: "Whenever he returned from court to his residence, he shut his doors and sat in silence; even before wife and children he could pass a whole day without speaking." },
  { zh: "或時袒跣奔躍，夫人問其故，洋曰：「為爾漫戲。", literal: "Sometimes he would run and leap barefoot; when his wife asked why, Yang said, \"Just playing around with you.", idiomatic: "Sometimes he ran and leaped barefoot; when his wife asked why, Yang said, \"Just playing around with you." },
  { zh: "」其實蓋欲習勞也。", literal: "\" In truth he was training himself to endure hardship.", idiomatic: "\" In truth he was training himself to endure hardship." },
  { zh: "澄獲徐州刺史蘭欽子京，以為膳奴，欽請贖之，不許；", literal: "Cheng captured Lan Qin's son Jing, son of Xuzhou Inspector Lan Qin, and made him a kitchen slave; Qin asked to ransom him and was refused;", idiomatic: "Cheng captured Lan Jing, son of Xuzhou inspector Lan Qin, and made him a kitchen slave; Qin asked to ransom him and was refused;" },
  { zh: "京屢自訴，澄杖之，曰：「更訴，當殺汝！", literal: "Jing repeatedly pleaded for himself; Cheng beat him and said, \"Plead again and I will kill you!", idiomatic: "Jing repeatedly pleaded for himself; Cheng beat him and said, \"Plead again and I will kill you!" },
  { zh: "」京與其黨六人謀作亂。", literal: "\" Jing and six of his companions plotted rebellion.", idiomatic: "\" Jing and six of his companions plotted rebellion." },
  { zh: "澄在鄴，居北城東柏堂，嬖琅邪公主，欲其往來無間，侍衛者常遣出外。", literal: "Cheng was at Ye, dwelling in the Eastern Cypress Hall of the north city; he favored the Princess of Langye and wished her comings and goings to be unhindered, so he often sent the guards outside.", idiomatic: "Cheng was at Ye, dwelling in the Eastern Cypress Hall of the north city; he favored the Princess of Langye and wished her comings and goings to be unhindered, so he often sent the guards outside." },
  { zh: "辛卯，澄與散騎常侍陳元康、吏部尚書侍中楊愔、黃門侍郎崔季舒屏左右，謀受魏禪，署擬百官。", literal: "On xinmao, Cheng, with Supernumerary Cavalier Attendant Chen Yuankang, Minister of Personnel and Attendant-in-Ordinary Yang Yin, and Yellow Gate Gentleman Cui Jishu, dismissed attendants and plotted to receive Wei abdication, drafting appointments for the hundred offices.", idiomatic: "On xinmao, Cheng, with supernumerary cavalier attendant Chen Yuankang, minister of personnel and attendant-in-ordinary Yang Yin, and yellow gate gentleman Cui Jishu, dismissed attendants and plotted to receive Wei abdication, drafting appointments for the hundred offices." },
  { zh: "蘭京進食，澄卻之，謂諸人曰：「昨夜夢此奴斫我，當急殺之。", literal: "Lan Jing brought food; Cheng refused it and said to the others, \"Last night I dreamed this slave hacked me—I must kill him at once.", idiomatic: "Lan Jing brought food; Cheng refused it and said to the others, \"Last night I dreamed this slave hacked me—I must kill him at once." },
  { zh: "」京聞之，置刀盤下，冒言進食。", literal: "\" Jing heard this, hid a knife under the tray, and forced his way in claiming to serve food.", idiomatic: "\" Jing heard this, hid a knife under the tray, and forced his way in claiming to serve food." },
  { zh: "澄怒曰：「我未索食，何為遽來！", literal: "Cheng angrily said, \"I did not ask for food—why come so suddenly!", idiomatic: "Cheng angrily said, \"I did not ask for food—why come so suddenly!" },
  { zh: "」京揮刀曰：「來殺汝！", literal: "\" Jing swung the knife and said, \"I have come to kill you!", idiomatic: "\" Jing swung the knife and said, \"I have come to kill you!" },
  { zh: "」澄自投傷足，入於床下，賊去床，弒之。", literal: "\" Cheng threw himself down, injuring his foot, and crawled under the bed; the assassins lifted the bed and killed him.", idiomatic: "\" Cheng threw himself down, injuring his foot, and crawled under the bed; the assassins lifted the bed and killed him." },
  { zh: "愔狼狽走出，遺一靴；", literal: "Yin fled in disarray, leaving one boot behind;", idiomatic: "Yin fled in disarray, leaving one boot behind;" },
  { zh: "季舒匿於廁中；", literal: "Jishu hid in the privy;", idiomatic: "Jishu hid in the privy;" },
  { zh: "元康以身蔽澄，與賊爭刀被傷，腸出；", literal: "Yuankang shielded Cheng with his body, struggled with the assassins for the blade, was wounded, and his intestines spilled out;", idiomatic: "Yuankang shielded Cheng with his body, struggled with the assassins for the blade, was wounded, and his intestines spilled out;" },
  { zh: "庫直王紘冒刃御賊；", literal: "Storehouse officer Wang Hong braved the blades to repel the assassins;", idiomatic: "Storehouse officer Wang Hong braved the blades to repel the assassins;" },
  { zh: "紇奚捨樂斗死。", literal: "Hong and Xi Shele fought and died.", idiomatic: "Hong and Xi Shele fought and died." },
  { zh: "時變起倉猝，內外震駭。", literal: "The crisis arose in sudden haste; inside and outside were shaken with terror.", idiomatic: "The crisis arose in sudden haste; inside and outside were shaken with terror." },
  { zh: "太原公洋在城東雙堂，聞之，神色不變，指揮部分，入討群賊，斬而臠之，徐出，言曰：「奴反，大將軍被傷，無大苦也。", literal: "Prince of Taiyuan Yang was in the Twin Hall east of the city; hearing of it, his expression did not change. He directed deployment, entered to suppress the assassins, cut them down and minced them, then came out slowly and said, \"The slaves rebelled; the Grand General was wounded—nothing serious.", idiomatic: "Prince Yang of Taiyuan was in the Twin Hall east of the city; hearing of it, his expression did not change. He directed deployment, entered to suppress the assassins, cut them down and minced them, then came out slowly and said, \"The slaves rebelled; the grand general was wounded—nothing serious." },
  { zh: "」內外莫不驚異。", literal: "\" Inside and outside, none were not astonished.", idiomatic: "\" Inside and outside, all were astonished." },
  { zh: "洋秘不發喪。", literal: "Yang kept the death secret and did not announce mourning.", idiomatic: "Yang kept the death secret and did not announce mourning." },
  { zh: "陳元康手書辭母，口占使功曹參軍祖珽作書陳便宜，至夜而卒；", literal: "Chen Yuankang wrote by hand a farewell to his mother and dictated for staff officer Zu Ting a memorial setting forth urgent measures; by night he died;", idiomatic: "Chen Yuankang wrote by hand a farewell to his mother and dictated for staff officer Zu Ting a memorial setting forth urgent measures; by night he died;" },
  { zh: "洋殯之第中，詐雲出使，虛除元康中書令。", literal: "Yang laid him out in the residence, falsely saying he had gone on mission, and posthumously appointed Yuankang Director of the Secretariat.", idiomatic: "Yang laid him out in the residence, falsely saying he had gone on mission, and posthumously appointed Yuankang director of the secretariat." },
  { zh: "以王紘為領左右都督。", literal: "He made Wang Hong Commander of the Left and Right Guards.", idiomatic: "He made Wang Hong commander of the left and right guards." },
  { zh: "紘，基之子也。", literal: "Hong was Ji's son.", idiomatic: "Hong was the son of Wang Ji." },
  { zh: "勳貴以重兵皆在并州，勸洋早如晉陽，洋從之。", literal: "The meritorious nobles, because the heavy troops were all at Bingzhou, urged Yang to go quickly to Jinyang; Yang agreed.", idiomatic: "The meritorious nobles, because the heavy troops were all at Bingzhou, urged Yang to go quickly to Jinyang; Yang agreed." },
  { zh: "夜，召大將軍督護太原唐邕，使部分將士，鎮遏四方；", literal: "At night he summoned Grand General Protector of Taiyuan Tang Yong and had him deploy officers and soldiers to secure and suppress all quarters;", idiomatic: "At night he summoned grand general protector of Taiyuan Tang Yong and had him deploy officers and soldiers to secure all quarters;" },
  { zh: "邕支配須臾而畢，洋由是重之。", literal: "Yong completed the deployment in a moment; Yang therefore valued him highly.", idiomatic: "Yong completed the deployment in a moment; Yang therefore valued him highly." },
  { zh: "癸巳，洋諷東魏主以立太子大赦。", literal: "On guisi, Yang prompted the Eastern Wei emperor to proclaim a general amnesty for installing the crown prince.", idiomatic: "On guisi, Yang prompted the Eastern Wei emperor to proclaim a general amnesty for installing the crown prince." },
  { zh: "澄死問漸露，東魏主竊謂左右曰：「大將軍今死，似是天意，威權當復歸帝室矣！", literal: "News of Cheng's death gradually leaked out; the Eastern Wei emperor secretly said to those around him, \"The Grand General is dead now—it seems heaven's will; authority should return to the imperial house!", idiomatic: "News of Cheng's death gradually leaked out; the Eastern Wei emperor secretly said to those around him, \"The grand general is dead now—it seems heaven's will; authority should return to the imperial house!" },
  { zh: "」洋留太尉高岳、太保高隆之、開府儀同三司司馬子如、侍中楊愔守鄴，餘勳貴皆自隨。", literal: "\" Yang left Grand Commandant Gao Yue, Grand Guardian Gao Longzhi, Equal in Honor to the Three Dukes Sima Ziru, and Attendant-in-Ordinary Yang Yin to hold Ye; the rest of the meritorious nobles all followed him.", idiomatic: "\" Yang left grand commandant Gao Yue, grand guardian Gao Longzhi, equal in honor to the three dukes Sima Ziru, and attendant-in-ordinary Yang Yin to hold Ye; the rest of the meritorious nobles all followed him." },
  { zh: "甲午，入謁東魏主於昭陽殿，從甲士八千人，登階者二百餘人，皆攘袂扣刃，若對嚴敵。", literal: "On jiawu, he entered to pay homage to the Eastern Wei emperor at Zhaoyang Hall with eight thousand armored soldiers; more than two hundred who ascended the steps all rolled up their sleeves and gripped their blades, as if facing a formidable foe.", idiomatic: "On jiawu, he entered to pay homage to the Eastern Wei emperor at Zhaoyang Hall with eight thousand armored soldiers; more than two hundred who ascended the steps all rolled up their sleeves and gripped their blades, as if facing a formidable foe." },
  { zh: "令主者傳奏曰：「臣有家事，須詣晉陽。", literal: "He had the usher transmit the memorial: \"Your servant has family business and must go to Jinyang.", idiomatic: "He had the usher transmit the memorial: \"Your servant has family business and must go to Jinyang." },
  { zh: "」再拜而出。", literal: "\" He bowed twice and withdrew.", idiomatic: "\" He bowed twice and withdrew." },
  { zh: "東魏主失色，目送之曰：「此人又似不相容，朕不知死在何日！", literal: "The Eastern Wei emperor turned pale; watching him go he said, \"This man again seems incompatible with me—I know not on what day I shall die!", idiomatic: "The Eastern Wei emperor turned pale; watching him go he said, \"This man again seems incompatible with me—I know not on what day I shall die!" },
  { zh: "」晉陽舊臣宿將素輕洋；", literal: "\" The old ministers and veteran generals of Jinyang had always looked down on Yang;", idiomatic: "\" The old ministers and veteran generals of Jinyang had always looked down on Yang;" },
  { zh: "及至，大會文武，神彩英暢，言辭敏洽，眾皆大驚。", literal: "when he arrived, he held a great assembly of civil and military officials; his spirit was bright and fluent, his words quick and apt—all were greatly astonished.", idiomatic: "when he arrived, he held a great assembly of civil and military officials; his spirit was bright and fluent, his words quick and apt—all were greatly astonished." },
  { zh: "澄政令有不便者，洋皆改之。", literal: "Where Cheng's policies and orders had been inconvenient, Yang changed them all.", idiomatic: "Where Cheng's policies and orders had been inconvenient, Yang changed them all." },
  { zh: "高隆之、司馬子如等惡度支尚書崔暹，奏暹及崔季舒過惡，鞭二百，徙邊。", literal: "Gao Longzhi, Sima Ziru, and others hated Revenue Minister Cui Xian; they memorialized Xian and Cui Jishu's faults and crimes—two hundred lashes and exile to the frontier.", idiomatic: "Gao Longzhi, Sima Ziru, and others hated revenue minister Cui Xian; they memorialized Xian and Cui Jishu's faults and crimes—two hundred lashes and exile to the frontier." },
  { zh: "侯景以宋子仙為司徙、郭元建為尚書左僕射，與領軍任約等四十人並開府儀同三司，仍詔：「自今開府儀同不須更加將軍。", literal: "Hou Jing made Song Zixian Minister of Works and Guo Yuanjian Left Vice Director of the Secretariat; with Army Commander Ren Yue and forty others he all made Equal in Honor to the Three Dukes with independent staffs, and also decreed: \"From now on, Equal in Honor to the Three Dukes need not additionally receive general's rank.", idiomatic: "Hou Jing made Song Zixian minister of works and Guo Yuanjian left vice director of the secretariat; with army commander Ren Yue and forty others he all made equal in honor to the three dukes with independent staffs, and also decreed: \"From now on, equal in honor to the three dukes need not additionally receive general's rank." },
  { zh: "」是後開府儀同至多，不可復記矣。", literal: "\" After this, those made Equal in Honor to the Three Dukes became so numerous they could no longer be recorded.", idiomatic: "\" After this, those made equal in honor to the three dukes became so numerous they could no longer be recorded." },
  { zh: "鄱陽王范自樅陽遣信告江州刺史尋陽王大心，大心遣信邀之。", literal: "Prince of Poyang Fan sent a message from Zongyang to inform Jiangzhou Inspector Prince of Xunyang Daxin; Daxin sent a message inviting him.", idiomatic: "Prince Xiao Fan of Poyang sent a message from Zongyang to inform Jiangzhou inspector Prince Daxin of Xunyang; Daxin sent a message inviting him." },
  { zh: "范引兵詣江州，大心以湓城處之。", literal: "Fan led his troops to Jiangzhou; Daxin lodged him at Pencheng.", idiomatic: "Fan led his troops to Jiangzhou; Daxin lodged him at Pencheng." },
  { zh: "吳興兵力寡弱，張嵊書生，不閒軍旅。", literal: "Wuxing's military strength was thin and weak; Zhang Sheng was a bookish man, unskilled in military affairs.", idiomatic: "Wuxing's military strength was thin and weak; Zhang Sheng was a bookish man, unskilled in military affairs." },
  { zh: "或勸嵊效袁君正以郡迎侯子鑒。", literal: "Some urged Sheng to follow Yuan Junzheng's example and welcome Hou Zijian with the commandery.", idiomatic: "Some urged Sheng to follow Yuan Junzheng's example and welcome Hou Zijian with the commandery." },
  { zh: "嵊歎曰：「袁氏世濟忠貞，不意君正一旦隳之。", literal: "Sheng sighed and said, \"The Yuan clan for generations upheld loyalty and integrity—I did not expect Junzheng to ruin it in a single day.", idiomatic: "Sheng sighed and said, \"The Yuan clan for generations upheld loyalty and integrity—I did not expect Junzheng to ruin it in a single day." },
  { zh: "吾豈不知吳郡既沒，吳興勢難久全；", literal: "Do I not know that once Wu Commandery has fallen, Wuxing can hardly long endure;", idiomatic: "Do I not know that once Wu Commandery has fallen, Wuxing can hardly long endure;" },
  { zh: "但以身許國，有死無貳耳！", literal: "but having pledged my body to the state, I have death and no second loyalty!", idiomatic: "but having pledged my body to the state, I have death and no second loyalty!" },
  { zh: "」九月，癸丑朔，子鑒軍至吳興，嵊戰敗，還府，整服安坐，子鑒執送建康。", literal: "\" In the ninth month, on the first day guichou, Zijian's army reached Wuxing; Sheng was defeated in battle, returned to his headquarters, dressed properly and sat at ease; Zijian seized him and sent him to Jiankang.", idiomatic: "\" In the ninth month, on the first day guichou, Zijian's army reached Wuxing; Sheng was defeated, returned to his headquarters, dressed properly and sat at ease; Zijian seized him and sent him to Jiankang." },
  { zh: "侯景嘉其守節，欲活之，嵊曰：「吾忝任專城，朝廷傾危，不能匡復，今日速死為幸！", literal: "Hou Jing admired his steadfast integrity and wished to spare him; Sheng said, \"I disgracefully held a walled city alone; the court totters and I could not restore it—quick death today is fortune!", idiomatic: "Hou Jing admired his steadfast integrity and wished to spare him; Sheng said, \"I disgracefully held a walled city alone; the court totters and I could not restore it—quick death today is fortune!" },
  { zh: "」景猶欲存其一子，嵊曰：「吾一門已在鬼錄，不就爾虜求恩！", literal: "\" Jing still wished to spare one of his sons; Sheng said, \"My whole house is already on the roll of ghosts—I will not beg favor from you rebels!", idiomatic: "\" Jing still wished to spare one of his sons; Sheng said, \"My whole house is already on the roll of ghosts—I will not beg favor from you rebels!" },
  { zh: "」景怒，盡殺之；", literal: "\" Jing in anger killed them all;", idiomatic: "\" Jing in anger killed them all;" },
  { zh: "並殺沈浚。", literal: "and also killed Shen Jun.", idiomatic: "and also killed Shen Jun." },
  { zh: "河東王譽告急於岳陽王察，察留咨議參軍濟陽蔡大寶守襄陽，帥眾二萬、騎二千伐江陵以救湘州。", literal: "Prince of Hedong Yu urgently reported to Prince of Yueyang Cha; Cha left advisory staff officer Cai Dabao of Jiyang to hold Xiangyang and led twenty thousand men and two thousand horse to attack Jiangling to save Xiang Province.", idiomatic: "Prince Xiao Yu of Hedong urgently reported to Prince Xiao Cha of Yueyang; Cha left advisory staff officer Cai Dabao of Jiyang to hold Xiangyang and led twenty thousand men and two thousand cavalry to attack Jiangling to save Xiang Province." },
  { zh: "湘東王繹大懼，遣左右就獄中問計於王僧辯，僧辯具陳方略，繹乃赦之，以為城中都督。", literal: "Prince of Xiangdong Yi was greatly afraid; he sent attendants to the prison to ask Wang Senbian for counsel; Senbian fully set forth his strategy; Yi then pardoned him and made him commander within the city.", idiomatic: "Prince Xiao Yi of Xiangdong was greatly afraid; he sent attendants to the prison to ask Wang Senbian for counsel; Senbian fully set forth his strategy; Yi then pardoned him and made him commander within the city." },
  { zh: "乙卯，察至江陵，作十三營以攻之；", literal: "On yimao, Cha reached Jiangling and built thirteen camps to attack it;", idiomatic: "On yimao, Cha reached Jiangling and built thirteen camps to attack it;" },
  { zh: "會大雨，平地水深四尺，察軍氣沮。", literal: "it happened to rain heavily; water on level ground was four chi deep, and Cha's army's morale sank.", idiomatic: "it happened to rain heavily; water on level ground was four chi deep, and Cha's army's morale sank." },
  { zh: "繹與新興太守杜崱有舊，密邀之。", literal: "Yi had old ties with Xinxing prefect Du Ya and secretly invited him.", idiomatic: "Yi had old ties with Xinxing prefect Du Ya and secretly invited him." },
  { zh: "乙丑，崱與兄岌、岸、弟幼安、兄子龕各帥所部降於繹。", literal: "On yichou, Ya, his elder brothers Ji and An, his younger brother You'an, and his elder brother's son Kan each led their units to surrender to Yi.", idiomatic: "On yichou, Ya, his elder brothers Ji and An, his younger brother You'an, and his elder brother's son Kan each led their units to surrender to Yi." },
  { zh: "岸請以五百騎襲襄陽，晝夜兼行，去襄陽三十里，城中覺之，蔡大寶奉察母龔保林登城拒戰。", literal: "An asked to take five hundred horse in a surprise attack on Xiangyang, traveling day and night by double stages; thirty li from Xiangyang the city detected them; Cai Dabao supported Cha's mother Gong Baolin in ascending the wall to resist.", idiomatic: "An asked to take five hundred cavalry in a surprise attack on Xiangyang, traveling day and night by double stages; thirty li from Xiangyang the city detected them; Cai Dabao supported Cha's mother Gong Baolin in ascending the wall to resist." },
  { zh: "察聞之，夜遁，棄糧食、金帛、鎧仗於湕水，不可勝紀。", literal: "Cha heard of it and fled by night, abandoning grain, gold, silk, armor, and weapons at the Ju River beyond counting.", idiomatic: "Cha heard of it and fled by night, abandoning grain, gold, silk, armor, and weapons at the Ju River beyond counting." },
  { zh: "張纘病足，察載以隨軍；", literal: "Zhang Zuan was ill in the foot; Cha carried him along with the army;", idiomatic: "Zhang Zuan was ill in the foot; Cha carried him along with the army;" },
  { zh: "及敗走，守者恐為追兵所及，殺之，棄屍而去。", literal: "when they were defeated and fled, the guards feared pursuit and killed him, leaving the corpse and going.", idiomatic: "when they were defeated and fled, the guards feared pursuit and killed him, leaving the corpse and going." },
  { zh: "察至襄陽，岸奔廣平，依其兄南陽太守□獻。", literal: "Cha reached Xiangyang; An fled to Guangping and relied on his elder brother, Nanyang prefect [Xian].", idiomatic: "Cha reached Xiangyang; An fled to Guangping and relied on his elder brother, Nanyang prefect [Xian]." },
  { zh: "湘東王繹以鮑泉圍長沙久不克，怒之，以平南將軍王僧辯代為都督，數泉十罪，命舍人羅重歡與僧辯偕行。", literal: "Prince of Xiangdong Yi, because Bao Quan besieged Changsha long without taking it, was angry; he replaced him with Pingnan General Wang Senbian as commander, counted ten crimes against Quan, and ordered Gentleman-Attendant Luo Chonghuan to go with Senbian.", idiomatic: "Prince Xiao Yi of Xiangdong, because Bao Quan besieged Changsha long without taking it, was angry; he replaced him with pingnan general Wang Senbian as commander, counted ten crimes against Quan, and ordered gentleman-attendant Luo Chonghuan to go with Senbian." },
  { zh: "泉聞僧辯來，愕然曰：「得王竟陵來助我，賊不足平。", literal: "Quan heard Senbian was coming and said in astonishment, \"To get Wang of Jingling to help me—the rebels are not worth crushing.", idiomatic: "Quan heard Senbian was coming and said in astonishment, \"To get Wang of Jingling to help me—the rebels are not worth crushing." },
  { zh: "」拂席待之。", literal: "\" He brushed the mat and awaited him.", idiomatic: "\" He brushed the mat and awaited him." },
  { zh: "僧辯入，背泉而坐，曰：「鮑郎，卿有罪，令旨使我鎖卿，卿勿以故意見期。", literal: "Senbian entered, sat with his back to Quan, and said, \"Master Bao, you are guilty; by order I am to fetter you—do not expect our old friendship.", idiomatic: "Senbian entered, sat with his back to Quan, and said, \"Master Bao, you are guilty; by order I am to fetter you—do not expect our old friendship." },
  { zh: "」使重歡宣令，鎖之床側。", literal: "\" He had Chonghuan proclaim the order and fettered him beside the bed.", idiomatic: "\" He had Chonghuan proclaim the order and fettered him beside the bed." },
  { zh: "泉為啟自申，且謝淹緩之罪，繹怒解，遂釋之。", literal: "Quan submitted a memorial in his own defense and also apologized for the delay; Yi's anger eased, and he was released.", idiomatic: "Quan submitted a memorial in his own defense and also apologized for the delay; Yi's anger eased, and he was released." },
  { zh: "冬，十月，癸未朔，東魏以開府儀同三司潘相樂為司空。", literal: "In winter, the tenth month, on the first day guiwei, Eastern Wei made Equal in Honor to the Three Dukes Pan Xiangle Minister of Works.", idiomatic: "In winter, the tenth month, on the first day guiwei, Eastern Wei made Pan Xiangle, equal in honor to the three dukes, minister of works." },
  { zh: "初，歷陽太守莊鐵帥眾歸尋陽王大心，大心以為豫章內史。", literal: "Earlier, Liyang prefect Zhuang Tie led his troops to submit to Prince of Xunyang Daxin; Daxin made him Administrator of Yuzhang.", idiomatic: "Earlier, Liyang prefect Zhuang Tie led his troops to submit to Prince Daxin of Xunyang; Daxin made him administrator of Yuzhang." },
  { zh: "鐵至郡即叛，推觀寧侯永為主。", literal: "Tie reached the commandery and immediately rebelled, setting up Marquis of Guanning Yong as leader.", idiomatic: "Tie reached the commandery and immediately rebelled, setting up Marquis Yong of Guanning as leader." },
  { zh: "永，范之弟也。", literal: "Yong was Fan's younger brother.", idiomatic: "Yong was Fan's younger brother." },
  { zh: "丁酉，鐵引兵襲尋陽，大心遣其將徐嗣徽逆擊，破之。", literal: "On dingyou, Tie led troops in a surprise attack on Xunyang; Daxin sent his general Xu Sihui to meet and strike him and defeated him.", idiomatic: "On dingyou, Tie led troops in a surprise attack on Xunyang; Daxin sent his general Xu Sihui to meet and strike him and defeated him." },
  { zh: "鐵走，至建昌，光遠將軍韋構邀擊之，鐵失其母弟妻子，單騎還南昌，大心遣構將兵追討之。", literal: "Tie fled; reaching Jianchang, Guangyuan General Wei Gou intercepted and struck him; Tie lost his mother, younger brother, wife, and children, returned alone on horseback to Nanchang; Daxin sent Gou leading troops in pursuit.", idiomatic: "Tie fled; reaching Jianchang, guangyuan general Wei Gou intercepted and struck him; Tie lost his mother, younger brother, wife, and children, returned alone on horseback to Nanchang; Daxin sent Gou leading troops in pursuit." },
  { zh: "宋子仙自吳郡趣錢塘。", literal: "Song Zixian from Wu Commandery pressed toward Qiantang.", idiomatic: "Song Zixian marched from Wu Commandery toward Qiantang." },
  { zh: "劉神茂自吳興趣富陽，前武州刺史富陽孫國恩以城降之。", literal: "Liu Shenmao from Wuxing pressed toward Fuyang; former Wuzhou Inspector Sun Guo'en of Fuyang surrendered the city to him.", idiomatic: "Liu Shenmao marched from Wuxing toward Fuyang; former Wuzhou inspector Sun Guo'en of Fuyang surrendered the city to him." },
  { zh: "十一月，乙卯，葬武皇帝於修陵，廟號高祖。", literal: "In the eleventh month, on yimao, the Martial Emperor was buried at Xiuling; his temple name was Gaozu.", idiomatic: "In the eleventh month, on yimao, the Martial Emperor was buried at Xiuling; his temple name was Gaozu." },
  { zh: "百濟遣使入貢，見城闕荒圮，異於向來，哭於端門；", literal: "Baekje sent envoys to pay tribute; seeing the city gates ruined and desolate, unlike before, they wept at the Duan Gate;", idiomatic: "Baekje sent envoys to pay tribute; seeing the city gates ruined and desolate, unlike before, they wept at the Duan Gate;" },
  { zh: "侯景怒，錄送莊嚴寺，不聽出。", literal: "Hou Jing was angry, seized them and sent them to Zhuangyan Temple, and would not let them leave.", idiomatic: "Hou Jing was angry, seized them and sent them to Zhuangyan Temple, and would not let them leave." },
  { zh: "壬戌，宋子仙急攻錢塘，戴僧逖降之。", literal: "On renxu, Song Zixian pressed the attack on Qiantang; Dai Sengti surrendered to him.", idiomatic: "On renxu, Song Zixian pressed the attack on Qiantang; Dai Sengti surrendered to him." },
  { zh: "岳陽王察使將軍薛暉攻廣平，拔之，獲杜岸，送襄陽。", literal: "Prince of Yueyang Cha sent General Xue Hui to attack Guangping, took it, captured Du An, and sent him to Xiangyang.", idiomatic: "Prince Xiao Cha of Yueyang sent general Xue Hui to attack Guangping, took it, captured Du An, and sent him to Xiangyang." },
  { zh: "察拔其舌，鞭其面，支解而烹之。", literal: "Cha pulled out his tongue, whipped his face, dismembered him, and boiled him.", idiomatic: "Cha pulled out his tongue, whipped his face, dismembered him, and boiled him." },
  { zh: "又發其祖父墓，焚其骸而揚之，以其頭為漆碗。", literal: "He also opened his grandfather's tomb, burned the bones and scattered the ashes, and made his skull into a lacquered bowl.", idiomatic: "He also opened his grandfather's tomb, burned the bones and scattered the ashes, and made his skull into a lacquered bowl." },
  { zh: "察既與湘東王繹為敵，恐不能自存，遣使求援於魏，請為附庸。", literal: "Cha, now enemy to Prince of Xiangdong Yi, feared he could not survive alone; he sent envoys to Wei to beg aid and asked to become a vassal.", idiomatic: "Cha, now enemy to Prince Xiao Yi of Xiangdong, feared he could not survive alone; he sent envoys to Western Wei to beg aid and asked to become a vassal." },
  { zh: "丞相泰令東閣祭酒榮權使於襄陽。", literal: "Chancellor Tai sent Eastern Pavilion Libationer Rong Quan as envoy to Xiangyang.", idiomatic: "Chancellor Yuwen Tai sent eastern pavilion libationer Rong Quan as envoy to Xiangyang." },
  { zh: "繹使司州刺史柳仲禮鎮竟陵以圖察，察懼，遣其妃王氏及世子察為質於魏。", literal: "Yi sent Sizhou Inspector Liu Zhongli to hold Jingling to plot against Cha; Cha was afraid and sent his consort Lady Wang and his heir Cha as hostages to Wei.", idiomatic: "Yi sent Sizhou inspector Liu Zhongli to hold Jingling to plot against Cha; Cha was afraid and sent his consort Lady Wang and his heir Cha as hostages to Western Wei." },
  { zh: "丞相泰欲經略江、漢，以開府儀同三司楊忠都督三荊等十五州諸軍事，鎮穰城。", literal: "Chancellor Tai wished to extend control over the Yangtze and Han; he made Equal in Honor to the Three Dukes Yang Zhong commander of all military affairs in the Three Jing and fifteen other provinces, stationed at Rangcheng.", idiomatic: "Chancellor Yuwen Tai wished to extend control over the Yangtze and Han; he made Yang Zhong, equal in honor to the three dukes, commander of all military affairs in the Three Jing and fifteen other provinces, stationed at Rangcheng." },
  { zh: "仲禮至安陸，安陸太守沈勰以城降之。", literal: "Zhongli reached Anlu; Anlu prefect Shen Ji surrendered the city to him.", idiomatic: "Zhongli reached Anlu; Anlu prefect Shen Ji surrendered the city to him." },
  { zh: "仲禮留長史馬岫與其弟子禮守之，帥眾一萬趣襄陽，泰遣楊忠及行台僕射長孫儉將兵擊仲禮以救察。", literal: "Zhongli left Chief Clerk Ma Xiu and his younger brother Zili to hold it, led ten thousand men toward Xiangyang; Tai sent Yang Zhong and Mobile Secretariat Vice Director Changsun Jian leading troops to strike Zhongli and save Cha.", idiomatic: "Zhongli left chief clerk Ma Xiu and his younger brother Zili to hold it, led ten thousand men toward Xiangyang; Yuwen Tai sent Yang Zhong and mobile secretariat vice director Changsun Jian with troops to strike Zhongli and save Cha." },
  { zh: "宋子仙乘勝度浙江，至會稽。", literal: "Song Zixian pressed the victory across the Zhe River and reached Kuaiji.", idiomatic: "Song Zixian pressed the victory across the Zhe River and reached Kuaiji." },
  { zh: "邵陵王綸聞錢塘已敗，出奔鄱陽，鄱陽內史開建侯蕃以兵拒之，范進擊蕃，破之。", literal: "Prince of Shaoling Lun heard Qiantang had fallen, fled toward Poyang; Poyang Administrator Marquis of Kaijian Fan resisted with troops; Prince of Poyang Fan advanced and struck Fan and defeated him.", idiomatic: "Prince Xiao Lun of Shaoling heard Qiantang had fallen and fled toward Poyang; Poyang administrator Marquis Fan of Kaijian resisted with troops; Prince Xiao Fan of Poyang advanced, struck Fan, and defeated him." },
  { zh: "魏楊忠將至義陽，太守馬伯符以下溠城降之，忠以伯符為鄉導。", literal: "Wei's Yang Zhong was about to reach Yiyang; prefect Ma Bofu below Xiachuan surrendered the city to him; Zhong made Bofu his guide.", idiomatic: "Western Wei's Yang Zhong was about to reach Yiyang; prefect Ma Bofu below Xiachuan surrendered the city to him; Zhong made Bofu his guide." },
  { zh: "伯符，岫之子也。", literal: "Bofu was Xiu's son.", idiomatic: "Bofu was Xiu's son." },
  { zh: "南郡王大連為東揚州刺史。", literal: "Prince of Nanjun Dalian was made Eastern Yangzhou Inspector.", idiomatic: "Prince Dalian of Nanjun was made Eastern Yangzhou inspector." },
  { zh: "時會稽豐沃，勝兵數萬，糧仗山積，東人懲侯景殘虐，鹹樂為用，而大連朝夕酣飲，不恤軍事；", literal: "At the time Kuaiji was rich and fertile, with tens of thousands of fit soldiers and grain and arms piled like mountains; the eastern people, chastened by Hou Jing's cruelty, all gladly served—yet Dalian drank day and night and did not care for military affairs;", idiomatic: "At the time Kuaiji was rich and fertile, with tens of thousands of fit soldiers and grain and arms piled like mountains; the eastern people, chastened by Hou Jing's cruelty, all gladly served—yet Dalian drank day and night and did not care for military affairs;" },
  { zh: "司馬東陽留異，凶狡殘暴，為眾所患，大連悉以軍事委之。", literal: "Eastern Yangzhou staff officer Liu Yi was fierce, cunning, and cruel, hated by all; Dalian entrusted all military affairs to him.", idiomatic: "Eastern Yangzhou staff officer Liu Yi was fierce, cunning, and cruel, hated by all; Dalian entrusted all military affairs to him." },
  { zh: "十二月，庚寅，宋子仙攻會稽，大連棄城走，異奔還鄉里，尋以其眾降於子仙。", literal: "In the twelfth month, on gengyin, Song Zixian attacked Kuaiji; Dalian abandoned the city and fled; Yi fled back to his home village, and soon surrendered his troops to Zixian.", idiomatic: "In the twelfth month, on gengyin, Song Zixian attacked Kuaiji; Dalian abandoned the city and fled; Yi fled back to his home village, and soon surrendered his troops to Zixian." },
  { zh: "大連欲奔鄱陽，異為子仙鄉導，追及大連於信安，執送建康，大連猶醉不之知。", literal: "Dalian wished to flee to Poyang; Yi served as Zixian's guide, overtook Dalian at Xin'an, seized him and sent him to Jiankang—Dalian was still drunk and knew nothing of it.", idiomatic: "Dalian wished to flee to Poyang; Yi served as Zixian's guide, overtook Dalian at Xin'an, seized him and sent him to Jiankang—Dalian was still drunk and knew nothing of it." },
  { zh: "帝聞之，引帷自蔽，掩袂而泣。", literal: "The emperor heard of it, drew the curtain to hide himself, and wept into his sleeve.", idiomatic: "The emperor heard of it, drew the curtain to hide himself, and wept into his sleeve." },
  { zh: "於是三吳盡沒於景，公侯在會稽者，俱南度嶺。", literal: "Thereupon the Three Wu regions all fell to Jing; nobles who had been at Kuaiji all crossed the mountains southward.", idiomatic: "Thereupon the Three Wu regions all fell to Jing; nobles who had been at Kuaiji all crossed the mountains southward." },
  { zh: "景以留異為東陽太守，收其妻子為質。", literal: "Jing made Liu Yi Administrator of Dongyang and took his wife and children as hostages.", idiomatic: "Jing made Liu Yi administrator of Dongyang and took his wife and children as hostages." },
  { zh: "乙酉，東魏以并州刺史彭樂為司徒。", literal: "On yiyou, Eastern Wei made Bingzhou Inspector Peng Yue Minister of Works.", idiomatic: "On yiyou, Eastern Wei made Bingzhou inspector Peng Yue minister of works." },
  { zh: "邵陵王綸進至九江，尋陽王大心以江州讓之，綸不受，引兵西上。", literal: "Prince of Shaoling Lun advanced to Jiujiang; Prince of Xunyang Daxin offered Jiangzhou to him; Lun did not accept and led his troops westward.", idiomatic: "Prince Xiao Lun of Shaoling advanced to Jiujiang; Prince Daxin of Xunyang offered Jiangzhou to him; Lun did not accept and led his troops westward." },
  { zh: "始興太守陳霸先結郡中豪傑欲討侯景，郡人侯安都、張人思等各帥眾千餘人歸之。", literal: "Shixing prefect Chen Baxian rallied the commandery's leading men to attack Hou Jing; commandery men Hou Andu, Zhang Rensi, and others each led more than a thousand men to join him.", idiomatic: "Shixing prefect Chen Baxian rallied the commandery's leading men to attack Hou Jing; commandery men Hou Andu, Zhang Rensi, and others each led more than a thousand men to join him." },
  { zh: "霸先遣主帥杜僧明將二千人頓於嶺上，廣州刺史蕭勃遣人止之曰：「侯景驍雄，天下無敵，前者援軍十萬，士馬精強，猶不能克，君以區區之眾，將何所之！", literal: "Baxian sent commander Du Sengming with two thousand men to encamp on the ridge; Guangzhou Inspector Xiao Bo sent someone to stop him, saying, \"Hou Jing is fierce and heroic, matchless under heaven; the earlier relief army of a hundred thousand with keen men and horses still could not defeat him—with your paltry force, where will you go!", idiomatic: "Baxian sent commander Du Sengming with two thousand men to encamp on the ridge; Guangzhou inspector Xiao Bo sent someone to stop him, saying, \"Hou Jing is fierce and heroic, matchless under heaven; the earlier relief army of a hundred thousand with keen men and horses still could not defeat him—with your paltry force, where will you go!" },
  { zh: "如聞嶺北王侯又皆鼎沸，親尋干戈，以君疏外，詎可暗投！", literal: "I hear the princes north of the ridge are all seething, seeking one another with weapons—for one of your distant station, how can you blindly throw yourself in!", idiomatic: "I hear the princes north of the ridge are all seething, seeking one another with weapons—for one of your distant station, how can you blindly throw yourself in!" },
  { zh: "未若且留始興，遙張聲勢，保太山之安也。", literal: "Better to stay at Shixing for now, raise a distant show of force, and keep the security of Mount Tai.", idiomatic: "Better to stay at Shixing for now, raise a distant show of force, and keep the security of Mount Tai." },
  { zh: "」霸先曰：「僕荷國恩，往聞侯景度江，即欲赴援，遭值元、蘭，梗我中道。", literal: "\" Baxian said, \"I bear the state's grace; when I first heard Hou Jing crossed the river, I wished at once to go to aid; I met Yuan and Lan blocking my mid-course.", idiomatic: "\" Baxian said, \"I bear the state's grace; when I first heard Hou Jing crossed the river, I wished at once to go to aid; I met Yuan and Lan blocking my mid-course." },
  { zh: "今京都覆沒，君辱臣死，誰敢愛命！", literal: "Now the capital has fallen; when the lord is shamed the minister dies—who dares cherish life!", idiomatic: "Now the capital has fallen; when the lord is shamed the minister dies—who dares cherish life!" },
  { zh: "君侯體則皇枝，任重方岳，遣僕一軍，猶賢乎已，乃更止之乎！", literal: "Your lordship by body is imperial branch, heavy with frontier responsibility—sending me one army is already more than I deserve, and now you would stop me!", idiomatic: "Your lordship by body is imperial branch, heavy with frontier responsibility—sending me one army is already more than I deserve, and now you would stop me!" },
  { zh: "」乃遣使間道詣江陵，受湘東王繹節度。", literal: "\" He then sent envoys by hidden route to Jiangling to accept Prince of Xiangdong Yi's command.", idiomatic: "\" He then sent envoys by hidden route to Jiangling to accept Prince Xiao Yi of Xiangdong's command." },
  { zh: "時南康土豪蔡路養起兵據郡，勃乃以腹心譚世遠為曲江令，與路養相結，同遏霸先。", literal: "At the time the local strongman of Nankang, Cai Luyang, raised troops and seized the commandery; Bo then made his trusted man Tan Shiyuan magistrate of Qujiang, allied with Luyang, and together blocked Baxian.", idiomatic: "At the time the local strongman of Nankang, Cai Luyang, raised troops and seized the commandery; Bo then made his trusted man Tan Shiyuan magistrate of Qujiang, allied with Luyang, and together blocked Baxian." },
  { zh: "魏楊忠拔隨郡，執太守桓和。", literal: "Wei's Yang Zhong took Suicheng and seized prefect Huan He.", idiomatic: "Western Wei's Yang Zhong took Suicheng and seized prefect Huan He." },
  { zh: "東魏使金門公潘樂等將兵五萬襲司州，刺史夏侯強降之。", literal: "Eastern Wei sent Prince of Jinmen Pan Yue and others leading fifty thousand troops in a surprise attack on Sizhou; Inspector Xiahou Qiang surrendered to them.", idiomatic: "Eastern Wei sent Prince Pan Yue of Jinmen and others with fifty thousand troops in a surprise attack on Sizhou; inspector Xiahou Qiang surrendered to them." },
  { zh: "於是東魏盡有淮南之地。", literal: "Thereupon Eastern Wei possessed all the land south of the Huai.", idiomatic: "Thereupon Eastern Wei possessed all the land south of the Huai." },
  { zh: "category:資治通鑑", literal: "category: Comprehensive Mirror in Aid of Governance", idiomatic: "category: Comprehensive Mirror in Aid of Governance" }
];
